import type { OAuthConnection, ProviderIdentity, TokenBundle } from "../types";
import {
  asString,
  fetchWithTimeout,
  firstNonEmpty,
  type JsonObject,
  readJson,
  tokenBundleFromOAuthJson,
} from "./util";

export type TokenExchangeInput = {
  connection: OAuthConnection;
  code: string;
  redirectUri: string;
  codeVerifier?: string;
};

export async function exchangeAuthorizationCode(input: TokenExchangeInput): Promise<TokenBundle> {
  const body = new URLSearchParams({
    grant_type: "authorization_code",
    code: input.code,
    redirect_uri: input.redirectUri,
    client_id: input.connection.client_id,
  });
  if (!input.connection.public_client) {
    body.set("client_secret", input.connection.client_secret);
  }
  if (input.codeVerifier) body.set("code_verifier", input.codeVerifier);

  const res = await fetchWithTimeout(input.connection.token_url, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });
  const raw = await readJson(res);
  if (!res.ok) {
    throw Object.assign(new Error(`token exchange failed: ${res.status}`), {
      status: 502,
      details: raw,
      upstream_status: res.status,
    });
  }
  return tokenBundleFromOAuthJson(raw);
}

export async function refreshAccessToken(
  connection: OAuthConnection,
  refreshToken: string,
): Promise<TokenBundle> {
  const body = new URLSearchParams({
    grant_type: "refresh_token",
    refresh_token: refreshToken,
    client_id: connection.client_id,
  });
  if (!connection.public_client) body.set("client_secret", connection.client_secret);

  const res = await fetchWithTimeout(connection.token_url, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });
  const raw = await readJson(res);
  if (!res.ok) {
    // A provider rejecting the grant (expired/revoked/already-rotated refresh
    // token) needs a reconnect, not a gateway retry. Callers treat 401 as an
    // expected "not connected" signal, while 502 reads as a broker outage.
    const grantRejected = res.status === 400 || res.status === 401;
    throw Object.assign(new Error(`refresh failed: ${res.status}`), {
      status: grantRejected ? 401 : 502,
      details: raw,
      upstream_status: res.status,
    });
  }
  const bundle = tokenBundleFromOAuthJson(raw);
  return {
    ...bundle,
    refresh_token: bundle.refresh_token ?? refreshToken,
  };
}

export async function fetchGenericIdentity(
  connection: OAuthConnection,
  accessToken: string,
): Promise<ProviderIdentity> {
  if (!connection.user_info_url) {
    throw Object.assign(new Error("generic oauth handler requires user_info_url"), { status: 500 });
  }
  const res = await fetchWithTimeout(connection.user_info_url, {
    headers: {
      Accept: "application/json",
      Authorization: `Bearer ${accessToken}`,
    },
  });
  const raw = await readJson(res);
  if (!res.ok) {
    throw Object.assign(new Error(`identity fetch failed: ${res.status}`), {
      status: 502,
      details: raw,
      upstream_status: res.status,
    });
  }
  return identityFromUserInfo(raw);
}

export function identityFromUserInfo(profile: JsonObject): ProviderIdentity {
  const providerUserId = firstNonEmpty(profile.sub, profile.id, profile.user_id, profile.userId);
  if (!providerUserId) {
    throw Object.assign(new Error("identity unavailable"), { status: 502 });
  }
  const accountName = firstNonEmpty(
    profile.login,
    profile.username,
    profile.preferred_username,
    providerUserId,
  );
  const displayName = firstNonEmpty(
    profile.display_name,
    profile.full_name,
    profile.name,
    profile.username,
    profile.login,
  );
  return {
    provider_user_id: providerUserId,
    provider_account_id: accountName,
    provider_account_name: accountName,
    email: asString(profile.email),
    display_name: displayName || undefined,
    metadata: profile,
  };
}

import { log } from "../log";
import type { OAuthConnection, ProviderIdentity, TokenBundle } from "../types";
import { attioIdentity } from "./attio";
import { calcomIdentity } from "./calcom";
import {
  exchangeAuthorizationCode,
  fetchGenericIdentity,
  refreshAccessToken,
  type TokenExchangeInput,
} from "./generic";
import { githubIdentity } from "./github";
import { gustoIdentity } from "./gusto";
import {
  exchangeHousecallProCode,
  housecallProIdentity,
  refreshHousecallProToken,
} from "./housecallpro";
import { hubspotIdentity } from "./hubspot";
import { jobberIdentity } from "./jobber";
import { linearIdentity } from "./linear";
import { mercuryIdentity } from "./mercury";
import { exchangeNotionCode, notionIdentity } from "./notion";
import { quickbooksIdentity } from "./quickbooks";
import { sageIdentity } from "./sage";
import { exchangeSlackCode, slackIdentity } from "./slack";
import { todoistIdentity } from "./todoist";
import { waveIdentity } from "./wave";
import { xeroIdentity } from "./xero";

export type Handler = {
  exchange(input: TokenExchangeInput): Promise<TokenBundle>;
  refresh(connection: OAuthConnection, refreshToken: string): Promise<TokenBundle>;
  identity(
    connection: OAuthConnection,
    accessToken: string,
    token: TokenBundle,
  ): Promise<ProviderIdentity>;
};

const genericHandler: Handler = {
  exchange: exchangeAuthorizationCode,
  refresh: refreshAccessToken,
  identity: (connection, accessToken) => fetchGenericIdentity(connection, accessToken),
};

function withGenericExchange(identity: Handler["identity"]): Handler {
  return {
    exchange: exchangeAuthorizationCode,
    refresh: refreshAccessToken,
    identity,
  };
}

const handlers: Record<string, Handler> = {
  generic: genericHandler,
  slack: {
    exchange: exchangeSlackCode,
    refresh: refreshAccessToken,
    identity: slackIdentity,
  },
  notion: {
    exchange: exchangeNotionCode,
    refresh: refreshAccessToken,
    identity: notionIdentity,
  },
  github: withGenericExchange(githubIdentity),
  linear: withGenericExchange(linearIdentity),
  calcom: withGenericExchange(calcomIdentity),
  jobber: withGenericExchange(jobberIdentity),
  mercury: withGenericExchange(mercuryIdentity),
  todoist: withGenericExchange(todoistIdentity),
  hubspot: withGenericExchange(hubspotIdentity),
  gusto: withGenericExchange(gustoIdentity),
  wave: withGenericExchange(waveIdentity),
  quickbooks: withGenericExchange(quickbooksIdentity),
  attio: withGenericExchange(attioIdentity),
  xero: withGenericExchange(xeroIdentity),
  housecallpro: {
    exchange: exchangeHousecallProCode,
    refresh: refreshHousecallProToken,
    identity: housecallProIdentity,
  },
  sage: withGenericExchange(sageIdentity),
};

export function resolveHandler(handlerKind: string, service?: string): Handler {
  const kind = handlerKind.trim().toLowerCase() || "generic";
  let handler = handlers[kind];
  if (!handler) {
    throw Object.assign(new Error(`unsupported handler_kind: ${handlerKind}`), { status: 500 });
  }

  // Catalyst one-release compatibility: generic rows fall back to slug handler.
  if (kind === "generic" && service) {
    const slug = service.trim().toLowerCase();
    const slugHandler = handlers[slug];
    if (slugHandler && slug !== "generic") {
      log.warn("oauth.handler.slug_fallback", {
        code: "deprecated_slug_fallback",
        provider: slug,
        handlerKind: kind,
        useHandlerKind: slug,
      });
      handler = slugHandler;
    }
  }
  return handler;
}

export const HANDLER_KINDS = Object.keys(handlers);

import { fetchWithTimeout, firstNonEmpty, readJson } from "../handlers/util";
import type { BrokerStore } from "../store/types";
import type { CredentialStrategy, OAuthConnection } from "../types";

const dcrLocks = new Map<string, Promise<OAuthConnection>>();
const DEFAULT_DCR_LOGO = "https://agentcompany.com/genesis/Icon.svg";

function needsDcr(connection: OAuthConnection): boolean {
  if (connection.credential_strategy !== "dcr") return false;
  const clientId = connection.client_id.trim();
  if (!clientId || clientId === "pending-dcr") return true;
  if (!connection.public_client && !connection.client_secret.trim()) return true;
  return false;
}

export async function ensureDcrCredentials(input: {
  store: BrokerStore;
  service: string;
  strategy: CredentialStrategy;
  connection: OAuthConnection;
  authBaseUrl: string;
  scopes: string[];
}): Promise<OAuthConnection> {
  if (!needsDcr(input.connection)) return input.connection;

  const lockKey = `${input.service}/${input.strategy}`;
  const inflight = dcrLocks.get(lockKey);
  if (inflight) return inflight;

  const run = (async () => {
    const latest = await input.store.getConnection(input.service, input.strategy);
    if (!latest) throw Object.assign(new Error("OAuth connection not found"), { status: 404 });
    if (!needsDcr(latest)) return latest;

    if (!latest.dcr_registration_url?.trim() || !latest.dcr_client_name?.trim()) {
      throw Object.assign(new Error("dcr registration config incomplete"), { status: 500 });
    }

    const redirectUri = `${input.authBaseUrl.replace(/\/$/, "")}/genesis/oauth/${input.service}/${input.strategy}/callback`;
    const scope = [...new Set(input.scopes.map((s) => s.trim()).filter(Boolean))].sort().join(" ");
    const body: Record<string, unknown> = {
      ...(latest.dcr_extra_registration_params ?? {}),
      redirect_uris: [redirectUri],
      client_name: latest.dcr_client_name.trim(),
      logo_uri: latest.dcr_logo_uri?.trim() || DEFAULT_DCR_LOGO,
      scope,
    };

    const res = await fetchWithTimeout(latest.dcr_registration_url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify(body),
    });
    const raw = await readJson(res);
    if (res.status < 200 || res.status >= 300) {
      throw Object.assign(new Error(`dcr registration failed: ${res.status}`), {
        status: 502,
        details: raw,
      });
    }

    const clientId = firstNonEmpty(raw.client_id);
    const clientSecret = firstNonEmpty(raw.client_secret);
    if (!clientId) {
      throw Object.assign(new Error("dcr registration response missing client_id"), {
        status: 502,
      });
    }
    if (!latest.public_client && !clientSecret) {
      throw Object.assign(new Error("dcr registration response missing client_secret"), {
        status: 502,
      });
    }

    return input.store.upsertConnection({
      ...latest,
      client_id: clientId,
      client_secret: clientSecret || latest.client_secret,
      dcr_registered_at: new Date(),
    });
  })();

  dcrLocks.set(lockKey, run);
  try {
    return await run;
  } finally {
    dcrLocks.delete(lockKey);
  }
}

import { log } from "../log";
import type { OAuthConnection, ProviderIdentity, TokenBundle } from "../types";
import { callMcpTool, mcpProfileFromResult } from "./mcp";
import {
  asString,
  decodeJwtClaims,
  fetchWithTimeout,
  firstNonEmpty,
  type JsonObject,
  readJson,
} from "./util";

/** Overridable in tests. */
export const mercuryConfig = {
  mcpUrl: "https://mcp.mercury.com/mcp",
  organizationUrl: "https://api.mercury.com/api/v1/organization",
};

/**
 * Mercury identity chain: MCP getOrganization → getAccounts →
 * (static only) REST /organization → JWT claims.
 *
 * Partner REST OAuth (oauth2.mercury.com / static) may hit api.mercury.com.
 * DCR mission tokens must not be forwarded there after an MCP outage.
 */
export async function mercuryIdentity(
  connection: OAuthConnection,
  accessToken: string,
  _token: TokenBundle,
): Promise<ProviderIdentity> {
  for (const tool of ["getOrganization", "getAccounts"] as const) {
    try {
      const mcp = await callMcpTool(mercuryConfig.mcpUrl, accessToken, tool);
      const profile = mcpProfileFromResult(mcp);
      if (profile) return mapMercuryProfile(profile);
    } catch (err) {
      log.debug("oauth.mercury.mcp_identity_failed", {
        code: "mcp_identity_failed",
        provider: "mercury",
        tool,
        err,
      });
    }
  }

  if (connection.credential_strategy === "static") {
    try {
      const identity = await fetchMercuryIdentityFromRest(accessToken);
      if (identity) return identity;
    } catch (err) {
      log.warn("oauth.mercury.rest_identity_failed", {
        code: "rest_identity_failed",
        provider: "mercury",
        strategy: "static",
        err,
      });
    }
  }

  const claims = decodeJwtClaims(accessToken);
  if (claims) return mapJwtIdentity(claims);
  log.error("oauth.mercury.identity_unavailable", {
    code: "identity_unavailable",
    provider: "mercury",
    strategy: connection.credential_strategy,
  });
  throw Object.assign(new Error("identity unavailable"), { status: 502 });
}

async function fetchMercuryIdentityFromRest(accessToken: string): Promise<ProviderIdentity> {
  const res = await fetchWithTimeout(mercuryConfig.organizationUrl, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: "application/json",
    },
  });
  const raw = await readJson(res);
  if (!res.ok) {
    throw Object.assign(new Error(`mercury organization status ${res.status}`), {
      status: 502,
      details: raw,
    });
  }
  return mapMercuryProfile(raw);
}

function mapMercuryProfile(profile: JsonObject): ProviderIdentity {
  const org =
    profile.organization &&
    typeof profile.organization === "object" &&
    !Array.isArray(profile.organization)
      ? (profile.organization as JsonObject)
      : profile;
  const providerUserId = firstNonEmpty(
    org.organizationId,
    org.organization_id,
    org.id,
    org.userId,
    org.user_id,
    profile.organizationId,
    profile.organization_id,
    profile.id,
    profile.userId,
    profile.user_id,
  );
  if (!providerUserId) {
    throw Object.assign(new Error("identity unavailable"), { status: 502 });
  }
  const accountName =
    firstNonEmpty(
      org.legalBusinessName,
      org.name,
      org.nickname,
      org.organizationName,
      profile.legalBusinessName,
      profile.name,
      profile.nickname,
      profile.organizationName,
    ) || undefined;
  return {
    provider_user_id: providerUserId,
    provider_account_id: providerUserId,
    provider_account_name: accountName,
    email: asString(org.email) ?? asString(profile.email),
    display_name: accountName || providerUserId,
    metadata: profile,
  };
}

function mapJwtIdentity(claims: JsonObject): ProviderIdentity {
  const providerUserId = firstNonEmpty(claims.sub, claims.user_id, claims.userId, claims.id);
  if (!providerUserId) {
    throw Object.assign(new Error("identity unavailable"), { status: 502 });
  }
  return {
    provider_user_id: providerUserId,
    email: asString(claims.email),
    display_name: firstNonEmpty(claims.name, claims.preferred_username) || undefined,
    metadata: claims,
  };
}

import type { OAuthConnection, ProviderIdentity, TokenBundle } from "../types";
import { fetchWithTimeout, firstNonEmpty, objectClaim, readJson, stringClaim } from "./util";

export async function gustoIdentity(
  _connection: OAuthConnection,
  accessToken: string,
  _token: TokenBundle,
): Promise<ProviderIdentity> {
  const res = await fetchWithTimeout("https://api.gusto.com/v1/token_info", {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: "application/json",
      "X-Gusto-API-Version": "2026-06-15",
    },
  });
  const raw = await readJson(res);
  if (!res.ok) {
    throw Object.assign(new Error("gusto token_info failed"), { status: 502, details: raw });
  }
  const resource = objectClaim(raw, "resource");
  const companyUUID = stringClaim(resource, "uuid");
  if (!companyUUID) {
    throw Object.assign(new Error("identity unavailable"), { status: 502 });
  }
  const resourceOwner = objectClaim(raw, "resource_owner");
  const ownerType = stringClaim(resourceOwner, "type");
  const ownerUUID = stringClaim(resourceOwner, "uuid");
  const accountName = firstNonEmpty(resource?.type, "Company");
  const displayName = ownerType ? `${accountName} · ${ownerType}` : accountName;
  const metadata: Record<string, unknown> = {};
  if (raw.scope != null) metadata.scope = raw.scope;
  if (resource) {
    metadata.resource = {
      type: stringClaim(resource, "type"),
      uuid: stringClaim(resource, "uuid"),
    };
  }
  if (resourceOwner) {
    metadata.resource_owner = {
      type: ownerType,
      uuid: ownerUUID,
    };
  }
  return {
    provider_user_id: companyUUID,
    provider_account_id: companyUUID,
    provider_account_name: accountName,
    display_name: displayName,
    target_type: ownerType || undefined,
    target_id: ownerUUID || undefined,
    metadata,
  };
}

import type { FileProvider, ProviderFileMetadata } from "../../domain/file";

export interface FileProviderAdapter {
