import { isExpectedBrokerOAuthTokenError } from "../../lib/genesis-oauth";
import { markProviderDriveFileStatus } from "../../storage/drive-file";
import { updateFileDriveSyncState } from "../../storage/file-drive";
import { revokeBoxDriveOAuth } from "../box-drive-connection";
import { BoxApiError, boxProvider } from "../file-providers/box";
import type { MountedCloudDriveDriver } from "./types";

export const boxMountedCloudDriveDriver: MountedCloudDriveDriver = {
  id: "box",
  driveKinds: ["box"],
  provider: boxProvider,
  listingStrategy: "lazy",
  resolveAccessToken: async (input) => {
    if (
      input.drive.kind !== "box" ||
      input.drive.ownerScopeType !== "user" ||
      input.drive.ownerScopeId !== input.userId ||
      input.drive.status === "disconnected"
    ) {
      return null;
    }
    try {
      const token = await boxProvider.getAccessToken(input.userId, { orgId: input.orgId });
      const tokenAccountId = await boxProvider.getAccountId?.(token);
      if (!tokenAccountId || tokenAccountId !== input.drive.providerAccountId) {
        await updateFileDriveSyncState({
          id: input.drive.id,
          status: "reauth_required",
          lastErrorCode: "box_account_mismatch",
        });
        return null;
      }
      return token;
    } catch (error) {
      if (boxProvider.isAuthorizationError?.(error)) {
        await updateFileDriveSyncState({
          id: input.drive.id,
          status: "reauth_required",
          lastErrorCode: "box_authorization_required",
        });
        return null;
      }
      if (isExpectedBrokerOAuthTokenError(error)) return null;
      throw error;
    }
  },
  disconnect: async (input) => {
    await revokeBoxDriveOAuth({ orgId: input.orgId, userId: input.userId });
  },
  handleAccessLoss: async (input) => {
    if (boxProvider.isAuthorizationError?.(input.error)) {
      await updateFileDriveSyncState({
        id: input.drive.id,
        status: "reauth_required",
        lastErrorCode: "box_authorization_required",
      });
      return false;
    }
    const itemAccessLost =
      boxProvider.isNotFoundError(input.error) ||
      (input.error instanceof BoxApiError && input.error.status === 403);
    if (!itemAccessLost || !input.file.providerObjectId) return false;
    await markProviderDriveFileStatus({
      orgId: input.orgId,
      driveId: input.drive.id,
      scope: { type: "user", id: input.userId },
      providerObjectId: input.file.providerObjectId,
      status: "unavailable",
    });
    return true;
  },
};

