import { inferDriveFileUploadMimeType } from "../../domain/drive-file-content-policy";
import type { ProviderFileMetadata } from "../../domain/file";
import { getGenesisOAuthToken } from "../../lib/genesis-oauth";
import type { FileProviderAdapter } from "./types";

const BOX_API_URL = "https://api.box.com/2.0";
const BOX_UPLOAD_URL = "https://upload.box.com/api/2.0";
export const BOX_FOLDER_MIME_TYPE = "application/vnd.box.folder";
export const BOX_OAUTH_SCOPES = ["root_readwrite", "ai.readwrite"] as const;

type BoxItem = {
  id?: unknown;
  type?: unknown;
  name?: unknown;
  size?: unknown;
  created_at?: unknown;
  modified_at?: unknown;
  trashed_at?: unknown;
  etag?: unknown;
  sha1?: unknown;
  extension?: unknown;
  parent?: { id?: unknown } | null;
  owned_by?: { name?: unknown; login?: unknown } | null;
};

type BoxItemCollection = {
  entries?: unknown;
  next_marker?: unknown;
};

type BoxUploadCollection = {
  entries?: unknown;
};

const BOX_ITEM_FIELDS = [
  "id",
  "type",
  "name",
  "size",
  "created_at",
  "modified_at",
  "trashed_at",
  "etag",
  "sha1",
  "extension",
  "parent",
  "owned_by",
].join(",");

export class BoxApiError extends Error {
  constructor(
    readonly status: number,
    readonly diagnosticDetail: string | null,
  ) {
    super("Box API request failed");
    this.name = "BoxApiError";
  }
}

function readString(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() ? value : undefined;
}

function isBoxFileOrFolderItem(value: unknown): value is BoxItem {
  if (!value || typeof value !== "object" || !("type" in value)) return false;
  return value.type === "file" || value.type === "folder";
}

function boxMimeType(item: BoxItem): string {
  if (item.type === "folder") return BOX_FOLDER_MIME_TYPE;
  const name = readString(item.name) ?? "file";
  const extension = readString(item.extension);
  return inferDriveFileUploadMimeType({
    name: extension && !name.includes(".") ? `${name}.${extension}` : name,
  });
}

export function boxItemToProviderMetadata(item: BoxItem): ProviderFileMetadata {
  const id = readString(item.id);
  const name = readString(item.name);
  const type = readString(item.type);
  if (!id || !name || (type !== "file" && type !== "folder")) {
    throw new Error("Box returned invalid file metadata");
  }
  const size = typeof item.size === "number" && Number.isSafeInteger(item.size) ? item.size : null;
  const ownerName = readString(item.owned_by?.name);
  const ownerEmail = readString(item.owned_by?.login);
  const parentId = readString(item.parent?.id);
  return {
    id,
    name,
    mimeType: boxMimeType(item),
    size: size == null ? null : String(size),
    createdTime: readString(item.created_at) ?? null,
    modifiedTime: readString(item.modified_at) ?? null,
    md5Checksum: readString(item.sha1) ?? null,
    version: readString(item.etag) ?? null,
    trashed: Boolean(readString(item.trashed_at)),
    parents: parentId ? [parentId] : null,
    owners:
      ownerName || ownerEmail
        ? [{ displayName: ownerName, emailAddress: ownerEmail, me: false }]
        : undefined,
  };
}

async function boxRequest(
  token: string,
  url: string,
  init?: RequestInit,
  timeoutMs: number | null = 30_000,
): Promise<Response> {
  const headers = new Headers(init?.headers);
  headers.set("Authorization", `Bearer ${token}`);
  headers.set("Accept", "application/json");
  const controller = !init?.signal && timeoutMs != null ? new AbortController() : null;
  const timeout = controller ? setTimeout(() => controller.abort(), timeoutMs ?? 0) : null;
  let response: Response;
  try {
    response = await fetch(url, {
      ...init,
      headers,
      signal: init?.signal ?? controller?.signal,
    });
  } finally {
    if (timeout) clearTimeout(timeout);
  }
  if (!response.ok) {
    const detail = (await response.text().catch(() => "")).slice(0, 4_000);
    throw new BoxApiError(response.status, detail || null);
  }
  return response;
}

async function boxJson<T>(token: string, url: string, init?: RequestInit): Promise<T> {
  const response = await boxRequest(token, url, init);
  // Box is an untyped HTTP boundary; callers validate fields before using them.
  return response.json() as Promise<T>;
}

async function boxItemRequest<T>(action: (type: "files" | "folders") => Promise<T>): Promise<T> {
  try {
    return await action("files");
  } catch (error) {
    if (!(error instanceof BoxApiError) || error.status !== 404) throw error;
    return action("folders");
  }
}

export async function getBoxAccountId(token: string): Promise<string> {
  const user = await boxJson<{ id?: unknown }>(token, `${BOX_API_URL}/users/me?fields=id`);
  const id = readString(user.id);
  if (!id) throw new Error("Box did not return account identity");
  return `box:${id}`;
}

async function getFileMetadata(
  token: string,
  providerFileId: string,
): Promise<ProviderFileMetadata> {
  const item = await boxItemRequest((type) =>
    boxJson<BoxItem>(
      token,
      `${BOX_API_URL}/${type}/${encodeURIComponent(providerFileId)}?fields=${BOX_ITEM_FIELDS}`,
    ),
  );
  return boxItemToProviderMetadata(item);
}

async function createFolder(token: string, name: string, parentId = "0"): Promise<string> {
  const item = await boxJson<BoxItem>(token, `${BOX_API_URL}/folders`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name, parent: { id: parentId } }),
  });
  const id = readString(item.id);
  if (!id) throw new Error("Box did not return the new folder id");
  return id;
}

async function uploadFile(
  token: string,
  folderId: string,
  name: string,
  content: Blob | string,
  mimeType: string,
): Promise<ProviderFileMetadata> {
  const body = new FormData();
  body.set("attributes", JSON.stringify({ name, parent: { id: folderId } }));
  body.set(
    "file",
    typeof content === "string" ? new Blob([content], { type: mimeType }) : content,
    name,
  );
  const result = await boxJson<BoxUploadCollection>(token, `${BOX_UPLOAD_URL}/files/content`, {
    method: "POST",
    body,
  });
  const entries = Array.isArray(result.entries) ? result.entries : [];
  const item = entries[0];
  if (!isBoxFileOrFolderItem(item)) throw new Error("Box did not return the uploaded file");
  return boxItemToProviderMetadata(item);
}

async function updateFileContent(
  token: string,
  providerFileId: string,
  content: Blob | string,
  mimeType: string,
): Promise<ProviderFileMetadata> {
  const body = new FormData();
  body.set(
    "file",
    typeof content === "string" ? new Blob([content], { type: mimeType }) : content,
    "file",
  );
  const result = await boxJson<BoxUploadCollection>(
    token,
    `${BOX_UPLOAD_URL}/files/${encodeURIComponent(providerFileId)}/content`,
    { method: "POST", body },
  );
  const entries = Array.isArray(result.entries) ? result.entries : [];
  const item = entries[0];
  if (!isBoxFileOrFolderItem(item)) throw new Error("Box did not return the updated file");
  return boxItemToProviderMetadata(item);
}

async function updateFileMetadata(
  token: string,
  providerFileId: string,
  metadata: Partial<Pick<ProviderFileMetadata, "name" | "trashed">>,
): Promise<ProviderFileMetadata> {
  if (metadata.trashed === true) {
    return trashFile(token, providerFileId);
  }
  const item = await boxItemRequest((type) =>
    boxJson<BoxItem>(token, `${BOX_API_URL}/${type}/${encodeURIComponent(providerFileId)}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(metadata.name ? { name: metadata.name } : {}),
    }),
  );
  return boxItemToProviderMetadata(item);
}

async function moveFile(
  token: string,
  providerFileId: string,
  targetFolderId: string,
): Promise<ProviderFileMetadata> {
  const item = await boxItemRequest((type) =>
    boxJson<BoxItem>(token, `${BOX_API_URL}/${type}/${encodeURIComponent(providerFileId)}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ parent: { id: targetFolderId } }),
    }),
  );
  return boxItemToProviderMetadata(item);
}

async function trashFile(token: string, providerFileId: string): Promise<ProviderFileMetadata> {
  await boxItemRequest((type) =>
    boxRequest(
      token,
      `${BOX_API_URL}/${type}/${encodeURIComponent(providerFileId)}${type === "folders" ? "?recursive=true" : ""}`,
      { method: "DELETE" },
    ),
  );
  // Box returns 204 and moves the item out of the normal collection. Callers
  // already have indexed metadata and only need confirmation of the state.
  return { id: providerFileId, name: providerFileId, trashed: true };
}

async function restoreFile(token: string, providerFileId: string): Promise<ProviderFileMetadata> {
  const item = await boxItemRequest((type) =>
    boxJson<BoxItem>(token, `${BOX_API_URL}/${type}/${encodeURIComponent(providerFileId)}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: "{}",
    }),
  );
  return boxItemToProviderMetadata(item);
}

async function deleteFile(token: string, providerFileId: string): Promise<void> {
  await boxItemRequest((type) =>
    boxRequest(token, `${BOX_API_URL}/${type}/${encodeURIComponent(providerFileId)}/trash`, {
      method: "DELETE",
    }),
  );
}

async function listFolderContentsPage(
  token: string,
  folderId: string,
  options?: { pageToken?: string; pageSize?: number },
): Promise<{ files: ProviderFileMetadata[]; nextPageToken?: string }> {
  const query = new URLSearchParams({
    fields: BOX_ITEM_FIELDS,
    usemarker: "true",
    limit: String(Math.min(1_000, Math.max(1, options?.pageSize ?? 1_000))),
  });
  if (options?.pageToken) query.set("marker", options.pageToken);
  const result = await boxJson<BoxItemCollection>(
    token,
    `${BOX_API_URL}/folders/${encodeURIComponent(folderId)}/items?${query}`,
  );
  const entries = Array.isArray(result.entries) ? result.entries : [];
  const files = entries.filter(isBoxFileOrFolderItem).map(boxItemToProviderMetadata);
  const nextPageToken = readString(result.next_marker);
  return { files, ...(nextPageToken ? { nextPageToken } : {}) };
}

async function listFolderContents(
  token: string,
  folderId: string,
): Promise<ProviderFileMetadata[]> {
  const files: ProviderFileMetadata[] = [];
  let pageToken: string | undefined;
  do {
    const page = await listFolderContentsPage(token, folderId, { pageToken });
    files.push(...page.files);
    pageToken = page.nextPageToken;
  } while (pageToken);
  return files;
}

async function searchFiles(
  token: string,
  queryText: string,
  options?: { limit?: number },
): Promise<ProviderFileMetadata[]> {
  const query = new URLSearchParams({
    query: queryText,
    ancestor_folder_ids: "0",
    fields: BOX_ITEM_FIELDS,
    limit: String(Math.min(100, Math.max(1, options?.limit ?? 20))),
  });
  const result = await boxJson<BoxItemCollection>(token, `${BOX_API_URL}/search?${query}`);
  const entries = Array.isArray(result.entries) ? result.entries : [];
  return entries.filter(isBoxFileOrFolderItem).map(boxItemToProviderMetadata);
}

async function listTrashedFiles(token: string): Promise<ProviderFileMetadata[]> {
  const files: ProviderFileMetadata[] = [];
  let marker: string | undefined;
  do {
    const query = new URLSearchParams({
      fields: BOX_ITEM_FIELDS,
      usemarker: "true",
      limit: "1000",
    });
    if (marker) query.set("marker", marker);
    const result = await boxJson<BoxItemCollection>(
      token,
      `${BOX_API_URL}/folders/trash/items?${query}`,
    );
    files.push(
      ...(Array.isArray(result.entries) ? result.entries : [])
        .filter(isBoxFileOrFolderItem)
        .map(boxItemToProviderMetadata),
    );
    marker = readString(result.next_marker);
  } while (marker);
  return files;
}

async function getFileContent(
  token: string,
  providerFileId: string,
  headers?: Record<string, string>,
): Promise<Response> {
  return boxRequest(token, `${BOX_API_URL}/files/${encodeURIComponent(providerFileId)}/content`, {
    headers,
  });
}

