import {
  type CatalystExchangeResponse,
  disconnectGenesisOAuthConnection,
  genesisAuthUrl,
  genesisOAuthPost,
  listGenesisOAuthIntegrations,
} from "../lib/genesis-oauth";
import { type FileDriveRecord, replaceBoxDriveMount } from "../storage/file-drive";
import { BOX_OAUTH_SCOPES } from "./file-providers/box";

export async function boxDriveOAuthConfigured(input: {
  orgId: string;
  userId: string;
}): Promise<boolean> {
  if (!genesisAuthUrl()) return false;
  try {
    const integrations = await listGenesisOAuthIntegrations(input.userId, {
      orgId: input.orgId,
      refresh: true,
    });
    return integrations.some(
      (integration) => integration.service === "box" || integration.slug === "box",
    );
  } catch {
    return false;
  }
}

export async function startBoxDriveOAuthAuthorize(input: {
  orgId: string;
  userId: string;
  redirectUri: string;
  state: string;
}): Promise<string> {
  const data = await genesisOAuthPost<{ auth_url: string }>(
    "box",
    "authorize",
    {
      redirect_uri: input.redirectUri,
      state: input.state,
      scopes: [...BOX_OAUTH_SCOPES],
      genesis_user_id: input.userId,
    },
    { orgId: input.orgId },
  );
  if (!data.auth_url?.trim()) throw new Error("Box authorize did not return an auth URL");
  return data.auth_url;
}

export async function completeBoxDriveOAuth(input: {
  orgId: string;
  userId: string;
  code: string;
}): Promise<{ drive: FileDriveRecord }> {
  const exchange = await genesisOAuthPost<CatalystExchangeResponse>(
    "box",
    "exchange",
    { code: input.code },
    { orgId: input.orgId },
  );
  if (exchange.genesis_user_id !== input.userId || exchange.org_id !== input.orgId) {
    throw new Error("Box connect identity did not match the current user and organization");
  }
  const providerUserId = exchange.provider_user_id?.trim();
  if (!providerUserId) throw new Error("Box connect did not return account identity");
  const accountLabel =
    exchange.email?.trim().toLowerCase() ||
    exchange.display_name?.trim() ||
    exchange.provider_account_name?.trim() ||
    providerUserId;

  const drive = await replaceBoxDriveMount({
    orgId: input.orgId,
    userId: input.userId,
    providerUserId,
    displayName: `Box · ${accountLabel}`,
  });
  return { drive };
}

export async function revokeBoxDriveOAuth(input: { orgId: string; userId: string }): Promise<void> {
  await disconnectGenesisOAuthConnection({
    provider: "box",
    genesisUserId: input.userId,
    orgId: input.orgId,
  });
}

import type { DriveFileRecord } from "../../storage/drive-file";
import type { FileDriveRecord } from "../../storage/file-drive";
import { refreshMountedCloudDriveFolderIndex } from "../mounted-cloud-drive-file-index";
import { boxMountedCloudDriveDriver } from "./box";
import { googleMountedCloudDriveDriver } from "./google-drive";
import type {
  MountedCloudDriveAccess,
  MountedCloudDriveAccessInput,
  MountedCloudDriveDriver,
} from "./types";

const MOUNTED_CLOUD_DRIVE_DRIVERS: readonly MountedCloudDriveDriver[] = [
  boxMountedCloudDriveDriver,
  googleMountedCloudDriveDriver,
];

export function getMountedCloudDriveDriver(driveKind: string): MountedCloudDriveDriver | null {
  return (
    MOUNTED_CLOUD_DRIVE_DRIVERS.find((driver) => driver.driveKinds.includes(driveKind)) ?? null
  );
}

export async function resolveMountedCloudDriveAccess(
  input: MountedCloudDriveAccessInput,
): Promise<MountedCloudDriveAccess | null> {
  const driver = getMountedCloudDriveDriver(input.drive.kind);
  if (!driver) return null;
  const token = await driver.resolveAccessToken(input);
  return token ? { driver, provider: driver.provider, token } : null;
}

export async function refreshLazyMountedCloudDriveFolder(input: {
  access: MountedCloudDriveAccess;
  orgId: string;
  userId: string;
  drive: FileDriveRecord;
  parentId: string | null;
  providerFolderId: string;
}): Promise<void> {
  if (input.access.driver.listingStrategy !== "lazy") return;
  await refreshMountedCloudDriveFolderIndex({
    orgId: input.orgId,
    userId: input.userId,
    drive: input.drive,
    provider: input.access.provider,
    token: input.access.token,
    parentId: input.parentId,
    providerFolderId: input.providerFolderId,
  });
}

export async function handleMountedCloudDriveAccessLoss(input: {
  access: MountedCloudDriveAccess;
  orgId: string;
  userId: string;
  userEmail?: string | null;
  drive: FileDriveRecord;
  file: DriveFileRecord;
  error: unknown;
}): Promise<boolean> {
  if (!input.access.driver.handleAccessLoss) return false;
  return input.access.driver.handleAccessLoss({
    orgId: input.orgId,
    userId: input.userId,
    userEmail: input.userEmail,
    drive: input.drive,
    token: input.access.token,
    file: input.file,
    error: input.error,
  });
}

