export type FileDriveRecord = typeof fileDrive.$inferSelect;

const GENESIS_CAPABILITIES = [
  "enumerate",
  "read",
  "range_read",
  "create_file",
  "create_folder",
  "upload",
  "rename",
  "move",
  "trash",
  "delete",
