  "search",
] as const;

export async function ensureGenesisDrives(input: {
  orgId: string;
  userId: string;
}): Promise<{ myDrive: FileDriveRecord; teamDrive: FileDriveRecord }> {
  const orgId = input.orgId.trim();
  const userId = input.userId.trim();
  if (!orgId) throw new Error("Organization ID is required");
  if (!userId) throw new Error("User ID is required");

  await db
    .insert(fileDrive)
    .values({
      orgId,
      kind: "genesis_s3",
      displayName: "Company Drive",
      ownerScopeType: "org",
      ownerScopeId: orgId,
      status: "active",
      capabilities: [...GENESIS_CAPABILITIES],
    })
    .onConflictDoNothing();

  const [teamDrive] = await db
    .select()
    .from(fileDrive)
    .where(
      and(
        eq(fileDrive.orgId, orgId),
        eq(fileDrive.kind, "genesis_s3"),
        eq(fileDrive.ownerScopeType, "org"),
        eq(fileDrive.ownerScopeId, orgId),
      ),
    )
    .limit(1);
  if (!teamDrive) throw new Error(`Failed to ensure Company Drive for organization ${orgId}`);

  await db
    .update(fileDrive)
    .set({
      displayName: "Company Drive",
      capabilities: [...GENESIS_CAPABILITIES],
      updatedAt: new Date(),
    })
    .where(eq(fileDrive.id, teamDrive.id));

  await db
    .insert(fileDrive)
    .values({
      orgId,
      kind: "genesis_s3",
      displayName: "My Drive",
      ownerScopeType: "user",
      ownerScopeId: userId,
      status: "active",
      capabilities: [...GENESIS_CAPABILITIES],
    })
    .onConflictDoNothing();

  const [myDrive] = await db
    .select()
    .from(fileDrive)
    .where(
      and(
        eq(fileDrive.orgId, orgId),
        eq(fileDrive.kind, "genesis_s3"),
        eq(fileDrive.ownerScopeType, "user"),
        eq(fileDrive.ownerScopeId, userId),
      ),
    )
    .limit(1);
  if (!myDrive) throw new Error(`Failed to ensure My Drive for user ${userId}`);

  await db
    .update(fileDrive)
    .set({ capabilities: [...GENESIS_CAPABILITIES], updatedAt: new Date() })
    .where(eq(fileDrive.id, myDrive.id));

  // Legacy Genesis metadata was user-scoped inside the single org mount. The
  // object keys already use the user prefix, so only the mount association
  // changes; no S3 objects are copied.
  await db
    .update(driveFile)
    .set({ driveId: myDrive.id, updatedAt: new Date() })
    .where(
      and(
        eq(driveFile.orgId, orgId),
        eq(driveFile.driveId, teamDrive.id),
        eq(driveFile.scopeType, "user"),
        eq(driveFile.scopeId, userId),
      ),
    );

  return {
    myDrive: { ...myDrive, capabilities: [...GENESIS_CAPABILITIES] },
    teamDrive: {
      ...teamDrive,
      displayName: "Company Drive",
      capabilities: [...GENESIS_CAPABILITIES],
    },
  };
}

export async function listFileDrives(orgId: string): Promise<FileDriveRecord[]> {
  const normalizedOrgId = orgId.trim();
  if (!normalizedOrgId) return [];
  return db
    .select()
    .from(fileDrive)
    .where(eq(fileDrive.orgId, normalizedOrgId))
    .orderBy(fileDrive.createdAt, fileDrive.displayName);
}

export async function listGoogleDriveMounts(): Promise<FileDriveRecord[]> {
  return db
    .select()
    .from(fileDrive)
    .where(inArray(fileDrive.kind, ["google_drive", "google_my_drive", "google_workspace_drive"]))
    .orderBy(fileDrive.updatedAt);
}

