export async function replaceBoxDriveMount(input: {
  orgId: string;
  userId: string;
  providerUserId: string;
  displayName: string;
}): Promise<FileDriveRecord> {
  const providerAccountId = `box:${input.providerUserId}`;
  const values = {
    orgId: input.orgId,
    kind: "box" as const,
    displayName: input.displayName,
    connectionId: input.providerUserId,
    ownerScopeType: "user" as const,
    ownerScopeId: input.userId,
    providerAccountId,
    providerRootId: "0",
    lastErrorCode: null,
    capabilities: [...BOX_DRIVE_CAPABILITIES] as string[],
    updatedAt: new Date(),
  };

  return db.transaction(async (tx) => {
    await tx.execute(
      sql`select pg_advisory_xact_lock(hashtextextended(${`box-drive-mount:${input.orgId}:${input.userId}`}, 0))`,
    );

    const [staged] = await tx
      .insert(fileDrive)
      .values({ ...values, status: "disconnected" })
      .onConflictDoUpdate({
        target: [
          fileDrive.orgId,
          fileDrive.kind,
          fileDrive.ownerScopeType,
          fileDrive.ownerScopeId,
          fileDrive.providerAccountId,
        ],
        set: { ...values, status: "disconnected" },
      })
      .returning();
    if (!staged) throw new Error("Failed to stage Box mount");

    await tx
      .update(fileDrive)
      .set({ status: "disconnected", lastErrorCode: null, updatedAt: new Date() })
      .where(
        and(
          eq(fileDrive.orgId, input.orgId),
          eq(fileDrive.kind, "box"),
          eq(fileDrive.ownerScopeType, "user"),
          eq(fileDrive.ownerScopeId, input.userId),
          ne(fileDrive.id, staged.id),
          ne(fileDrive.status, "disconnected"),
        ),
      );

    const [drive] = await tx
      .update(fileDrive)
      .set({ ...values, status: "active" })
      .where(eq(fileDrive.id, staged.id))
      .returning();
    if (!drive) throw new Error("Failed to mount Box");
    return drive;
  });
}

export async function disconnectBoxDriveMount(input: {
  orgId: string;
  userId: string;
  driveId: string;
}): Promise<FileDriveRecord | null> {
  const [drive] = await db
    .update(fileDrive)
    .set({ status: "disconnected", lastErrorCode: null, updatedAt: new Date() })
    .where(
      and(
        eq(fileDrive.id, input.driveId),
        eq(fileDrive.orgId, input.orgId),
        eq(fileDrive.kind, "box"),
        eq(fileDrive.ownerScopeType, "user"),
        eq(fileDrive.ownerScopeId, input.userId),
      ),
    )
    .returning();
  return drive ?? null;
}

