    expect(replaceBoxDriveMountMock).not.toHaveBeenCalled();
  });

  it("delegates account replacement to the atomic mount operation", async () => {
    genesisOAuthPostMock.mockResolvedValue({
      org_id: "org-1",
      genesis_user_id: "user-1",
      user_id: "user-1",
      provider_user_id: "new-box-user",
