    });
    const { completeBoxDriveOAuth } = await import("./box-drive-connection");

    await completeBoxDriveOAuth({ orgId: "org-1", userId: "user-1", code: "exchange-code" });
    expect(replaceBoxDriveMountMock).toHaveBeenCalledWith({
      orgId: "org-1",
      userId: "user-1",
      providerUserId: "new-box-user",
      displayName: "Box · new-box-user",
    });
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import type { FileDriveRecord } from "../../storage/file-drive";
import * as fileDriveStorage from "../../storage/file-drive";
import { boxProvider } from "../file-providers/box";
import { getMountedCloudDriveDriver, resolveMountedCloudDriveAccess } from "./index";

const BOX_DRIVE = {
  id: "drive-box",
  orgId: "org-1",
  kind: "box",
  displayName: "Box · ada@example.com",
  connectionId: "box-user-1",
  ownerScopeType: "user",
  ownerScopeId: "user-1",
  providerAccountId: "box:box-user-1",
