// File metadata can come from external providers and future driver-backed sources.
// Keep these open-ended while still documenting the known values used today.
export const DEFAULT_FILE_PROVIDER_ID = "google_drive" as const;
export type FileProvider = "google_drive" | "notion" | string;
export type FileSource = "generated" | "uploaded" | "referenced" | string;
export type FileStatus = "active" | "unavailable" | string;

export function parseFileSizeBytes(value: string | number | null | undefined): number | null {
  if (value === null || value === undefined) return null;
  if (typeof value === "string" && !/^\d+$/.test(value)) return null;
  const size = typeof value === "number" ? value : Number(value);
  return Number.isSafeInteger(size) && size >= 0 ? size : null;
}

export function getGoogleNativePreviewMimeType(
  mimeType: string | null | undefined,
): "application/pdf" | null {
  if (mimeType === "application/vnd.google-apps.document") return "application/pdf";
  if (mimeType === "application/vnd.google-apps.spreadsheet") return "application/pdf";
  if (mimeType === "application/vnd.google-apps.presentation") return "application/pdf";
  return null;
}

export interface FileReference {
  id: string;
  userId: string;
  orgId: string;
  provider: FileProvider;
  providerFileId: string;
  name: string;
  mimeType: string | null;
  source: FileSource;
  folderId: string | null;
  size: string | null;
  providerCreatedAt: Date | null;
  providerModifiedAt: Date | null;
  providerOwnerName: string | null;
  providerOwnerEmail: string | null;
  lastVerifiedAt: Date | null;
  status: FileStatus;
  createdAt: Date;
}

export interface ProviderFileMetadata {
  id: string;
  name: string;
  mimeType?: string | null;
  size?: string | null;
  createdTime?: string | null;
  modifiedTime?: string | null;
  md5Checksum?: string | null;
  version?: string | null;
  trashed?: boolean | null;
  parents?: string[] | null;
  owners?: Array<{
    displayName?: string | null;
    emailAddress?: string | null;
    me?: boolean | null;
  }>;
}

