const MAX_BULK_FILE_ACTION_IDS = 100;
const MAX_LEGACY_RELAY_UPLOAD_BYTES = 25 * 1024 * 1024;
const BULK_FILE_ACTIONS = new Set(["trash", "restore", "move", "delete", "unindex"]);

function secureContentHeaders(name: string, mimeType: string): Headers {
  return new Headers({
    "Content-Type": mimeType,
    "Content-Disposition": driveFileContentDisposition(name, mimeType),
    "Content-Security-Policy": DRIVE_FILE_CONTENT_SECURITY_POLICY,
    "X-Content-Type-Options": "nosniff",
    "Cache-Control": "private, max-age=60",
  });
}

function safeFileName(value: string): string {
  const name = value.replaceAll("\\", "/").split("/").at(-1)?.trim();
  if (!name || name === "." || name === "..") throw new Error("Invalid file name");
  return [...name]
    .map((character) => {
      const code = character.charCodeAt(0);
      return code <= 31 || code === 127 ? "_" : character;
    })
    .join("");
}

async function assertAvailableParent(input: {
  parentId: string | null;
  orgId: string;
  driveId: string;
  scope: ViewerFileScope;
}) {
  if (!input.parentId) return null;
  const parent = await getScopedDriveFile({
    id: input.parentId,
    orgId: input.orgId,
    scope: input.scope,
  });
  if (parent?.driveId !== input.driveId || parent.kind !== "folder" || parent.status !== "active") {
    throw new Error("The destination folder is not available");
  }
  return parent;
}

async function assertUniqueSiblingName(input: {
  name: string;
  parentId: string | null;
  orgId: string;
  driveId: string;
  scope: ViewerFileScope;
  excludeId?: string;
}) {
  const siblings = await listDriveFiles({
    orgId: input.orgId,
    driveId: input.driveId,
    scope: input.scope,
    parentId: input.parentId,
  });
  const normalized = input.name.toLocaleLowerCase();
  if (
    siblings.some(
      (sibling) =>
        sibling.id !== input.excludeId && sibling.name.toLocaleLowerCase() === normalized,
    )
  ) {
    throw new Error(`A file or folder named ${input.name} already exists here`);
  }
}

async function availableSiblingName(input: {
  name: string;
  parentId: string | null;
  orgId: string;
  driveId: string;
  scope: ViewerFileScope;
}): Promise<string> {
  const siblings = await listDriveFiles({
    orgId: input.orgId,
    driveId: input.driveId,
    scope: input.scope,
    parentId: input.parentId,
  });
  const names = new Set(siblings.map((sibling) => sibling.name.toLocaleLowerCase()));
  if (!names.has(input.name.toLocaleLowerCase())) return input.name;
  const dot = input.name.lastIndexOf(".");
  const hasExtension = dot > 0;
  const stem = hasExtension ? input.name.slice(0, dot) : input.name;
  const extension = hasExtension ? input.name.slice(dot) : "";
  for (let suffix = 2; suffix <= 100; suffix += 1) {
    const candidate = `${stem} ${suffix}${extension}`;
    if (!names.has(candidate.toLocaleLowerCase())) return candidate;
  }
  throw new Error("Too many files with this name");
}

const NEW_FILE_TEMPLATES = {
  markdown: {
    name: "Untitled.md",
    kind: "markdown",
    mimeType: "text/markdown",
    driveKinds: ["genesis_s3", "box"],
  },
  google_doc: {
    name: "Untitled document",
    kind: "document",
    mimeType: "application/vnd.google-apps.document",
    driveKinds: ["google_workspace_drive"],
  },
  google_sheet: {
    name: "Untitled spreadsheet",
    kind: "spreadsheet",
    mimeType: "application/vnd.google-apps.spreadsheet",
    driveKinds: ["google_workspace_drive"],
  },
  google_slide: {
    name: "Untitled presentation",
    kind: "presentation",
    mimeType: "application/vnd.google-apps.presentation",
    driveKinds: ["google_workspace_drive"],
  },
} as const;

async function collectFolderTreeIds(input: {
  rootId: string;
  orgId: string;
  driveId: string;
  scope: ViewerFileScope;
  status: "active" | "trashed";
}): Promise<string[]> {
  const records = await listDriveFiles({
    orgId: input.orgId,
    driveId: input.driveId,
    scope: input.scope,
    status: input.status,
  });
  const ids = [input.rootId];
  for (let cursor = 0; cursor < ids.length; cursor += 1) {
    const parentId = ids[cursor];
    for (const record of records) {
      if (record.parentId === parentId && !ids.includes(record.id)) ids.push(record.id);
    }
  }
  return ids;
}

async function buildFolderBreadcrumbs(input: {
  parentId: string | null;
  orgId: string;
  scope: ViewerFileScope;
}) {
  const breadcrumbs: Array<{ id: string; name: string }> = [];
  let currentId = input.parentId;
  const seen = new Set<string>();
  while (currentId && !seen.has(currentId)) {
    seen.add(currentId);
    const current = await getScopedDriveFile({
      id: currentId,
      orgId: input.orgId,
      scope: input.scope,
    });
    if (current?.kind !== "folder") break;
    breadcrumbs.unshift({ id: current.id, name: current.name });
    currentId = current.parentId;
  }
  return breadcrumbs;
}

/** Exported for regression tests (kind must not be stolen by a mismatched MIME). */
export function classifyFile(mimeType: string, name: string): string {
  const media = normalizeDriveFileMediaType(mimeType);
  if (media === "application/pdf") return "pdf";
  if (media.startsWith("image/") || /\.svg$/i.test(name)) return "image";
  if (media.startsWith("video/") || /\.(mp4|webm|mov|m4v)$/i.test(name)) return "video";
  if (media.startsWith("audio/") || /\.(mp3|wav|m4a|aac|ogg|oga|flac|opus|weba)$/i.test(name)) {
    return "audio";
  }
  if (media.includes("spreadsheet") || /\.(csv|tsv|xlsx?)$/i.test(name)) return "spreadsheet";
  if (media === "text/markdown" || /\.md$/i.test(name)) return "markdown";
  if (media === "application/json" || /\.json$/i.test(name)) return "document";
  if (media.startsWith("text/") || media.includes("document")) return "document";
  return "other";
}

function fileResponse(file: Awaited<ReturnType<typeof getScopedDriveFile>>, childCount?: number) {
  if (!file) return null;
  return {
    id: file.id,
    driveId: file.driveId,
    name: file.name,
    kind: file.kind,
    mimeType: file.mimeType,
    sizeBytes: file.sizeBytes,
    modifiedAt: file.providerModifiedAt?.toISOString() ?? file.updatedAt.toISOString(),
    parentId: file.parentId,
    status: file.status,
    ownerName: file.providerOwnerName,
    providerObjectId: file.providerObjectId,
    childCount: file.kind === "folder" ? (childCount ?? 0) : undefined,
  };
}

function viewerScopeForDrive(
  drive: Awaited<ReturnType<typeof getFileDrive>>,
  viewer: { orgId: string; userId: string },
): ViewerFileScope | null {
  return drive ? fileDriveScopeForViewer(drive, viewer) : null;
}

function driveSupports(
  drive: Awaited<ReturnType<typeof getFileDrive>>,
  capability: FileDriveCapability,
): boolean {
  return Boolean(drive?.capabilities.includes(capability));
}

function notifyDriveScopeChanged(input: {
  orgId: string;
  userId: string;
  driveId: string;
  scope: ViewerFileScope;
}) {
  notifyDriveFilesChanged({
    orgId: input.orgId,
    ownerUserId: input.scope.type === "org" ? null : input.userId,
    driveId: input.driveId,
  });
}

const GOOGLE_MY_DRIVE_OAUTH_STATE_TTL_SECONDS = 15 * 60;
const BOX_DRIVE_OAUTH_STATE_TTL_SECONDS = 15 * 60;

const filesNextRoutes = new Hono<Env>()
  .get("/drive-files/box/status", requirePermission("files.view"), async (c) => {
    const user = await c.var.auth.getUser();
    const orgId = resolveTenantOrgIdForWrite();
    return c.json({
      configured: await boxDriveOAuthConfigured({ orgId, userId: user.id }),
    });
  })
  .get("/drive-files/box/connect", requirePermission("files.view"), async (c) => {
    const user = await c.var.auth.getUser();
    const orgId = resolveTenantOrgIdForWrite();
    if (!(await boxDriveOAuthConfigured({ orgId, userId: user.id }))) {
      return c.json({ error: "Box OAuth is not available for this organization." }, 503);
    }
    const returnTo = c.req.query("returnTo")?.trim() || "/files";
    const state = base64url(randomBytes(24));
    await cache.set(
      `box_drive_oauth:${state}`,
      JSON.stringify({ userId: user.id, orgId, returnTo }),
      BOX_DRIVE_OAUTH_STATE_TTL_SECONDS,
    );
    try {
      const redirectUri = `${getAppBaseUrl(c)}/api/drive-files/box/callback`;
      const authUrl = await startBoxDriveOAuthAuthorize({
        orgId,
        userId: user.id,
        redirectUri,
        state,
      });
      return c.redirect(authUrl);
    } catch (error) {
      c.var.logger.error(
        "[box-drive] authorize failed",
        error instanceof Error ? error.message : error,
      );
      return c.json(
        { error: error instanceof Error ? error.message : "Could not start Box connection" },
        503,
      );
    }
  })
  .get("/drive-files/box/callback", async (c) => {
    const state = c.req.query("state")?.trim() || "";
    const code = c.req.query("code")?.trim() || "";
    const providerError = c.req.query("error")?.trim();
    const raw = state ? await cache.get(`box_drive_oauth:${state}`) : null;
    if (state) await cache.delete(`box_drive_oauth:${state}`);
    type BoxOAuthState = { userId: string; orgId: string; returnTo: string };
    let payload: BoxOAuthState | null = null;
    try {
      payload = raw ? (JSON.parse(String(raw)) as BoxOAuthState) : null;
    } catch {
      payload = null;
    }
    const returnTo = payload?.returnTo || "/files";
    const redirectWith = (
      status: "connected" | "error",
      options?: { reason?: string; driveId?: string },
    ) => {
      const destination = new URL(returnTo, c.req.url);
      destination.searchParams.set("boxDrive", status);
      if (options?.reason) destination.searchParams.set("boxDriveReason", options.reason);
      if (status === "connected" && options?.driveId) {
        destination.searchParams.set("drive", options.driveId);
        destination.searchParams.delete("driveFolder");
        destination.searchParams.delete("place");
        destination.searchParams.delete("provider");
        destination.searchParams.delete("googleLocation");
        destination.searchParams.delete("file");
      }
      return c.redirect(`${destination.pathname}${destination.search}`);
    };
    if (providerError) return redirectWith("error", { reason: "provider_denied" });
    if (!code) return redirectWith("error", { reason: "missing_code" });
    if (!payload) return redirectWith("error", { reason: "expired_state" });
    try {
      const result = await completeBoxDriveOAuth({
        orgId: payload.orgId,
        userId: payload.userId,
        code,
      });
      return redirectWith("connected", { driveId: result.drive.id });
    } catch (error) {
      c.var.logger.warn(
        "[box-drive] OAuth callback failed",
        error instanceof Error ? error.message : error,
      );
      const reason =
        error instanceof Error && /account identity/i.test(error.message)
