}

/**
 * Split stored Google My Drive display names (`Google My Drive · user@…`) so the
 * account can render on a second line in narrow sidebars.
 */
export function splitGoogleMyDriveLabel(name: string | null | undefined): {
  title: string;
  account: string | null;
} {
  const raw = name?.trim() || "Google My Drive";
  const separator = " · ";
  const index = raw.indexOf(separator);
  if (index === -1) {
    return { title: raw, account: null };
  }
  const title = raw.slice(0, index).trim() || "Google My Drive";
  const account = raw.slice(index + separator.length).trim() || null;
  return { title, account };
}

