type ServiceAccountCredential = {
  clientId: string;
  clientEmail: string;
  projectId: string;
};

function parseServiceAccountCredential(value: unknown): ServiceAccountCredential | null {
  if (!value || typeof value !== "object") {
    return null;
  }

  const credential = value as Record<string, unknown>;
  if (
    credential.type !== "service_account" ||
    typeof credential.client_id !== "string" ||
    !/^\d+$/.test(credential.client_id) ||
    typeof credential.client_email !== "string" ||
    credential.client_email.length === 0 ||
    typeof credential.project_id !== "string" ||
    credential.project_id.length === 0 ||
    typeof credential.private_key_id !== "string" ||
    credential.private_key_id.length === 0 ||
    typeof credential.private_key !== "string" ||
    !credential.private_key.includes("BEGIN PRIVATE KEY")
  ) {
    return null;
  }

  return {
    clientId: credential.client_id,
    clientEmail: credential.client_email,
    projectId: credential.project_id,
  };
}

