const SLUG_PATTERN = /^[a-z][a-z0-9_-]{0,47}$/;

/**
 * When a slug collides with a built-in connection (e.g. linear), auto-suffix
 * so Settings / agents can still add a user MCP without a reserved-slug error.
 */
export function allocateNonReservedUserMcpSlug(base: string): string {
  const cleaned = base
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
  if (cleaned && SLUG_PATTERN.test(cleaned) && !USER_MCP_RESERVED_SLUGS.has(cleaned)) {
    return cleaned;
  }
  const stem = (cleaned && SLUG_PATTERN.test(cleaned) ? cleaned : "mcp").slice(0, 40);
  const withMcp = `${stem}_mcp`.slice(0, 48);
  if (SLUG_PATTERN.test(withMcp) && !USER_MCP_RESERVED_SLUGS.has(withMcp)) {
    return withMcp;
  }
  for (let i = 2; i <= 20; i++) {
    const candidate = `${stem.slice(0, 40)}_mcp${i}`.slice(0, 48);
    if (SLUG_PATTERN.test(candidate) && !USER_MCP_RESERVED_SLUGS.has(candidate)) {
      return candidate;
    }
  }
  // Browser-safe fallback (no node crypto).
  const rand = Math.random().toString(36).slice(2, 10);
  return `mcp_${rand}`;
}

export function normalizeUserMcpSlug(raw: string | undefined, displayName: string): string {
  const fromInput = raw?.trim().toLowerCase() ?? "";
  if (fromInput) {
    const cleaned = fromInput
      .replace(/[^a-z0-9_-]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 48);
    if (!cleaned || !SLUG_PATTERN.test(cleaned)) {
      throw new Error(
        "Use a slug like acme_tools: start with a letter, then letters, numbers, _ or -.",
      );
    }
    return allocateNonReservedUserMcpSlug(cleaned);
  }
  const fromName = displayName
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .replace(/_+/g, "_")
    .slice(0, 48);
  if (fromName && SLUG_PATTERN.test(fromName)) {
    return allocateNonReservedUserMcpSlug(fromName);
  }
  return allocateNonReservedUserMcpSlug(`mcp_${Math.random().toString(36).slice(2, 10)}`);
}

