export type JsonObject = Record<string, unknown>;

export const OAUTH_HTTP_TIMEOUT_MS = 10_000;
export const MCP_MAX_BYTES = 1 << 20;

export async function fetchWithTimeout(
  input: string | URL | Request,
  init: RequestInit = {},
  timeoutMs = OAUTH_HTTP_TIMEOUT_MS,
): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(input, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

export async function readJson(res: Response): Promise<JsonObject> {
  const raw = await res.json().catch(async () => ({ error: await res.text() }));
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { error: "invalid_json" };
  return raw as JsonObject;
}

export function asString(value: unknown): string | undefined {
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return undefined;
}

export function firstNonEmpty(...values: unknown[]): string {
  for (const value of values) {
    const s = asString(value)?.trim();
    if (s) return s;
  }
  return "";
}

export function claim(obj: JsonObject | null | undefined, key: string): unknown {
  if (!obj) return undefined;
  return obj[key];
}

export function stringClaim(obj: JsonObject | null | undefined, key: string): string {
  return asString(claim(obj, key))?.trim() ?? "";
}

export function objectClaim(obj: JsonObject | null | undefined, key: string): JsonObject | null {
  const value = claim(obj, key);
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  return value as JsonObject;
}

export function decodeJwtClaims(accessToken: string): JsonObject | null {
  const parts = accessToken.split(".");
  if (parts.length < 2) return null;
  try {
    const payload = Buffer.from(parts[1]!, "base64url").toString("utf8");
    const parsed = JSON.parse(payload) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return null;
    return parsed as JsonObject;
  } catch {
    return null;
  }
}

export function tokenBundleFromOAuthJson(raw: JsonObject): {
  access_token: string;
  refresh_token?: string;
  expires_at: Date | null;
  scopes: string[];
  token_type: string;
  raw: JsonObject;
} {
  const access = firstNonEmpty(raw.access_token);
  if (!access) {
    throw Object.assign(new Error("token response missing access_token"), { status: 502 });
  }
  const expiresIn = Number(raw.expires_in ?? 0);
  const scope = asString(raw.scope);
  return {
    access_token: access,
    refresh_token: asString(raw.refresh_token),
    expires_at: expiresIn > 0 ? new Date(Date.now() + expiresIn * 1000) : null,
    scopes: scope ? scope.split(/[,\s]+/).filter(Boolean) : [],
    token_type: asString(raw.token_type) ?? "Bearer",
    raw,
  };
}

