import type { OAuthConnection, ProviderIdentity, TokenBundle } from "../types";
import {
  fetchWithTimeout,
  firstNonEmpty,
  objectClaim,
  readJson,
  stringClaim,
} from "./util";

export const dropboxConfig = {
  currentAccountUrl: "https://api.dropboxapi.com/2/users/get_current_account",
};

export async function dropboxIdentity(
  _connection: OAuthConnection,
  accessToken: string,
  _token: TokenBundle,
): Promise<ProviderIdentity> {
  const response = await fetchWithTimeout(dropboxConfig.currentAccountUrl, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: "application/json",
      "Content-Type": "application/json",
    },
    body: "{}",
  });
  const profile = await readJson(response);
  if (!response.ok) {
    throw Object.assign(new Error(`dropbox account identity failed: ${response.status}`), {
      status: 502,
      details: profile,
      upstream_status: response.status,
    });
  }

  const accountId = stringClaim(profile, "account_id");
  if (!accountId) {
    throw Object.assign(new Error("identity unavailable"), { status: 502 });
  }
  const name = objectClaim(profile, "name");
  const email = stringClaim(profile, "email") || undefined;
  const displayName =
    firstNonEmpty(
      name?.display_name,
      name?.familiar_name,
      name?.abbreviated_name,
      email,
      accountId,
    ) || undefined;

  return {
    provider_user_id: accountId,
    provider_account_id: accountId,
    provider_account_name: email || displayName,
    email,
    display_name: displayName,
    metadata: profile,
  };
}

import { afterEach, describe, expect, it, vi } from "vitest";
import { dropboxConfig, dropboxIdentity } from "./dropbox";

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe("dropboxIdentity", () => {
  it("loads the current Dropbox account through the required POST endpoint", async () => {
    const fetchMock = vi.fn<typeof fetch>().mockResolvedValue(
      Response.json({
        account_id: "dbid:THISISAVERYLONGANDVERYOBVIOUSTESTACCOUNT",
        email: "ada@example.com",
        name: {
          display_name: "Ada Lovelace",
          familiar_name: "Ada",
          abbreviated_name: "AL",
        },
        root_info: {
          ".tag": "user",
          root_namespace_id: "123456789",
          home_namespace_id: "123456789",
        },
      }),
    );
    vi.stubGlobal("fetch", fetchMock);

    await expect(dropboxIdentity({} as never, "dropbox-token", {} as never)).resolves.toMatchObject({
      provider_user_id: "dbid:THISISAVERYLONGANDVERYOBVIOUSTESTACCOUNT",
      provider_account_id: "dbid:THISISAVERYLONGANDVERYOBVIOUSTESTACCOUNT",
      provider_account_name: "ada@example.com",
      email: "ada@example.com",
      display_name: "Ada Lovelace",
    });

    expect(fetchMock).toHaveBeenCalledWith(
      dropboxConfig.currentAccountUrl,
      expect.objectContaining({ method: "POST", body: "{}" }),
    );
    const headers = new Headers(fetchMock.mock.calls[0]?.[1]?.headers);
    expect(headers.get("Authorization")).toBe("Bearer dropbox-token");
  });

  it("rejects responses without a stable Dropbox account id", async () => {
    vi.stubGlobal("fetch", vi.fn<typeof fetch>().mockResolvedValue(Response.json({ email: "ada@example.com" })));

    await expect(dropboxIdentity({} as never, "dropbox-token", {} as never)).rejects.toThrow(
      "identity unavailable",
    );
  });
});

