export async function replaceDropboxDriveMount(input: {
  orgId: string;
  userId: string;
  providerUserId: string;
  displayName: string;
}): Promise<FileDriveRecord> {
  const providerAccountId = `dropbox:${input.providerUserId}`;
  const values = {
    orgId: input.orgId,
    kind: "dropbox" as const,
    displayName: input.displayName,
    connectionId: input.providerUserId,
    ownerScopeType: "user" as const,
    ownerScopeId: input.userId,
    providerAccountId,
    providerRootId: "dropbox-root",
    lastErrorCode: null,
    capabilities: [...DROPBOX_DRIVE_CAPABILITIES] as string[],
    updatedAt: new Date(),
  };

  return db.transaction(async (tx) => {
    await tx.execute(
      sql`select pg_advisory_xact_lock(hashtextextended(${`dropbox-drive-mount:${input.orgId}:${input.userId}`}, 0))`,
    );

    const [staged] = await tx
      .insert(fileDrive)
      .values({ ...values, status: "disconnected" })
      .onConflictDoUpdate({
        target: [
          fileDrive.orgId,
          fileDrive.kind,
          fileDrive.ownerScopeType,
          fileDrive.ownerScopeId,
          fileDrive.providerAccountId,
        ],
        set: { ...values, status: "disconnected" },
      })
      .returning();
    if (!staged) throw new Error("Failed to stage Dropbox mount");

    await tx
      .update(fileDrive)
      .set({ status: "disconnected", lastErrorCode: null, updatedAt: new Date() })
      .where(
        and(
          eq(fileDrive.orgId, input.orgId),
          eq(fileDrive.kind, "dropbox"),
          eq(fileDrive.ownerScopeType, "user"),
          eq(fileDrive.ownerScopeId, input.userId),
          ne(fileDrive.id, staged.id),
          ne(fileDrive.status, "disconnected"),
        ),
      );

    const [drive] = await tx
      .update(fileDrive)
      .set({ ...values, status: "active" })
      .where(eq(fileDrive.id, staged.id))
      .returning();
    if (!drive) throw new Error("Failed to mount Dropbox");
    return drive;
  });
}

