import { describe, expect, test } from "vitest";
import {
  canReadDriveFileContent,
  fileDriveScopeForViewer,
  genesisCorpusForDrive,
  genesisStorageScopeForFileScope,
  isBoxFileDriveKind,
  isGoogleFileDriveKind,
  isGoogleMyDriveKind,
  isMountedCloudFileDriveKind,
} from "./file-drive";

const viewer = { orgId: "org_1", userId: "user_1" };

describe("file drive authority", () => {
  test("keeps content readable while a file is in trash", () => {
    expect(canReadDriveFileContent("active")).toBe(true);
    expect(canReadDriveFileContent("trashed")).toBe(true);
    expect(canReadDriveFileContent("unavailable")).toBe(false);
  });

  test("maps the viewer's Genesis mount to personal storage", () => {
    const drive = {
      kind: "genesis_s3",
      ownerScopeType: "user",
      ownerScopeId: "user_1",
    };
    expect(fileDriveScopeForViewer(drive, viewer)).toEqual({ type: "user", id: "user_1" });
    expect(genesisCorpusForDrive(drive)).toBe("my_drive");
  });

  test("maps the organization Genesis mount to shared storage", () => {
    const drive = {
      kind: "genesis_s3",
      ownerScopeType: "org",
      ownerScopeId: "org_1",
    };
    expect(fileDriveScopeForViewer(drive, viewer)).toEqual({ type: "org", id: "org_1" });
    expect(genesisCorpusForDrive(drive)).toBe("team_drive");
  });

  test("does not expose another user's personal mount", () => {
    expect(
      fileDriveScopeForViewer(
        { kind: "genesis_s3", ownerScopeType: "user", ownerScopeId: "user_2" },
        viewer,
      ),
    ).toBeNull();
  });

  test("uses matching S3 partitions", () => {
    expect(genesisStorageScopeForFileScope({ type: "user", id: "user_1" })).toEqual({
      type: "user",
      userId: "user_1",
    });
    expect(genesisStorageScopeForFileScope({ type: "org", id: "org_1" })).toEqual({
      type: "org",
      orgId: "org_1",
    });
  });

  test("exposes Google My Drive and Workspace mounts to their owner", () => {
    expect(
      fileDriveScopeForViewer(
        { kind: "google_my_drive", ownerScopeType: "user", ownerScopeId: "user_1" },
        viewer,
      ),
    ).toEqual({ type: "user", id: "user_1" });
    expect(
      fileDriveScopeForViewer(
        { kind: "google_workspace_drive", ownerScopeType: "user", ownerScopeId: "user_1" },
        viewer,
      ),
    ).toEqual({ type: "user", id: "user_1" });
    expect(isGoogleFileDriveKind("google_my_drive")).toBe(true);
    expect(isGoogleMyDriveKind("google_workspace_drive")).toBe(false);
  });

  test("exposes Box mounts only to their owner", () => {
    expect(
      fileDriveScopeForViewer(
        { kind: "box", ownerScopeType: "user", ownerScopeId: "user_1" },
        viewer,
      ),
    ).toEqual({ type: "user", id: "user_1" });
    expect(
      fileDriveScopeForViewer(
        { kind: "box", ownerScopeType: "user", ownerScopeId: "user_2" },
        viewer,
      ),
    ).toBeNull();
    expect(isBoxFileDriveKind("box")).toBe(true);
    expect(isMountedCloudFileDriveKind("box")).toBe(true);
    expect(isGoogleFileDriveKind("box")).toBe(false);
  });

  test("does not expose another user's Workspace mounts", () => {
    expect(
      fileDriveScopeForViewer(
        { kind: "google_workspace_drive", ownerScopeType: "user", ownerScopeId: "user_2" },
        viewer,
      ),
    ).toBeNull();
  });
});

import { describe, expect, it } from "vitest";
import {
  isBoxFileDriveKind,
  isGenesisFileDriveKind,
  isGoogleFileDriveKind,
  isMountedCloudFileDriveKind,
} from "./file-drive-kinds";

describe("client file drive kinds", () => {
  it("keeps Genesis, Google, and Box classifications disjoint", () => {
    expect(isGenesisFileDriveKind("genesis_s3")).toBe(true);
    expect(isGenesisFileDriveKind("box")).toBe(false);
    expect(isGoogleFileDriveKind("google_workspace_drive")).toBe(true);
    expect(isGoogleFileDriveKind("box")).toBe(false);
    expect(isBoxFileDriveKind("box")).toBe(true);
    expect(isMountedCloudFileDriveKind("box")).toBe(true);
    expect(isMountedCloudFileDriveKind("google_my_drive")).toBe(true);
    expect(isMountedCloudFileDriveKind("genesis_s3")).toBe(false);
  });
});

import { describe, expect, test } from "vitest";
import {
  coverMcpCatalogHit,
  integrationIdHintFromMcpDomain,
  matchNativeIntegrationForMcpCatalogHit,
  mcpCatalogProductKey,
  normalizeMcpCatalogDomain,
  userMcpNativeOverlapBadgeLabel,
  userMcpNativeOverlapConnectUrl,
  userMcpNativeOverlapDialogDescription,
  userMcpNativeOverlapDialogTitle,
  userMcpNativeOverlapMcpActionLabel,
  userMcpNativeOverlapPrimaryActionLabel,
} from "./user-mcp-native-overlap";

const natives = [
  { id: "box", name: "Box", connected: false, syncCapable: false },
  { id: "linear", name: "Linear", connected: false, syncCapable: false },
  { id: "hubspot", name: "HubSpot", connected: true, syncCapable: true },
  { id: "notion", name: "Notion", connected: false, syncCapable: false },
  { id: "calcom", name: "Cal.com", connected: false, syncCapable: false },
] as const;

describe("user-mcp-native-overlap", () => {
  test("normalizes catalog domains", () => {
    expect(normalizeMcpCatalogDomain("https://Linear.app/foo")).toBe("linear.app");
    expect(normalizeMcpCatalogDomain("www.notion.so")).toBe("notion.so");
  });

  test("maps known MCP domains to integration ids", () => {
    expect(integrationIdHintFromMcpDomain("box.com")).toBe("box");
    expect(integrationIdHintFromMcpDomain("mcp.box.com")).toBe("box");
    expect(integrationIdHintFromMcpDomain("linear.app")).toBe("linear");
    expect(integrationIdHintFromMcpDomain("mcp.linear.app")).toBe("linear");
    expect(integrationIdHintFromMcpDomain("mcp.hubspot.com")).toBe("hubspot");
    expect(integrationIdHintFromMcpDomain("cal.com")).toBe("calcom");
    expect(integrationIdHintFromMcpDomain("notion.com")).toBe("notion");
    expect(integrationIdHintFromMcpDomain("makenotion.com")).toBe("notion");
    expect(integrationIdHintFromMcpDomain("mcp.notion.com")).toBe("notion");
  });

  test("not connected: concise copy, connect URL, no Settings navigation", () => {
    const overlap = matchNativeIntegrationForMcpCatalogHit(
      {
        domain: "linear.app",
        name: "Linear",
        slug: "linear",
      },
      natives,
    );
    expect(overlap).toEqual({
      integrationId: "linear",
      integrationName: "Linear",
      connected: false,
      syncCapable: false,
    });
    expect(userMcpNativeOverlapBadgeLabel(overlap!)).toBe("Also in Third Party");
    expect(userMcpNativeOverlapDialogTitle(overlap!)).toBe("Linear is also a Genesis connection");
    const description = userMcpNativeOverlapDialogDescription(overlap!);
    expect(description).toContain("built-in Linear connection");
    expect(description).toContain("generic MCP tools");
    expect(description).not.toContain("Settings");
    expect(description).not.toContain("Third Party");
    expect(userMcpNativeOverlapPrimaryActionLabel(overlap!)).toBe("Connect Linear");
    expect(userMcpNativeOverlapMcpActionLabel(overlap!)).toBe("Add as MCP server");
    expect(userMcpNativeOverlapConnectUrl(overlap!)).toBe(
      "/api/integrations/linear/oauth?return_to=%2Fsettings%2Fintegrations%3Ftab%3Dmcp%26mcpView%3Dservers",
    );
  });

  test("connected: disconnect warning and keep/mcp labels", () => {
    const overlap = matchNativeIntegrationForMcpCatalogHit(
      { domain: "hubspot.com", name: "HubSpot" },
      natives,
    );
    expect(overlap?.connected).toBe(true);
    expect(overlap?.syncCapable).toBe(true);
    expect(userMcpNativeOverlapBadgeLabel(overlap!)).toBe("Connected in Third Party");
    expect(userMcpNativeOverlapDialogTitle(overlap!)).toBe("HubSpot is already connected");
    const description = userMcpNativeOverlapDialogDescription(overlap!);
    expect(description).toContain("already use HubSpot");
    expect(description).toContain("disconnects HubSpot");
    expect(description).toContain("two-way data sync");
    expect(description).not.toContain("Settings →");
    expect(userMcpNativeOverlapPrimaryActionLabel(overlap!)).toBe("Keep HubSpot");
    expect(userMcpNativeOverlapMcpActionLabel(overlap!)).toBe(
      "Use MCP instead (disconnects HubSpot)",
    );
  });

  test("does not match unrelated catalog products", () => {
    expect(
      matchNativeIntegrationForMcpCatalogHit(
        { domain: "neon.tech", name: "Neon", slug: "neon" },
        natives,
      ),
    ).toBeNull();
  });

  test("matches by product name when domain is unknown but name aligns", () => {
    const overlap = matchNativeIntegrationForMcpCatalogHit(
      { domain: "example-mcp.vendor.io", name: "Notion" },
      natives,
    );
    expect(overlap?.integrationId).toBe("notion");
  });

  test("matches Notion MCP aliases (makenotion.com, Notion MCP name/slug)", () => {
    expect(
      matchNativeIntegrationForMcpCatalogHit(
        { domain: "makenotion.com", name: "makenotion.com", slug: "makenotion-com" },
        natives,
      )?.integrationId,
    ).toBe("notion");
    expect(
