import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, test } from "vitest";
import {
  loadOAuthProviderMcpConfig,
  mcpConfigToTemplateDelivery,
  oauthProviderMcpConfigHashFragment,
  resolveMcpTemplateDelivery,
  resolveOAuthProvidersDir,
} from "./oauth-provider-mcp-delivery";

const monorepoWebRoot = join(dirname(fileURLToPath(import.meta.url)), "../..");
const providersDir = join(monorepoWebRoot, "tools/genesis/oauth-providers");

describe("oauth-provider-mcp-delivery", () => {
  test("resolveOAuthProvidersDir finds fixtures from apps/web cwd", () => {
    expect(resolveOAuthProvidersDir(monorepoWebRoot)).toBe(providersDir);
  });

  test("loads remote mcp_config from the Box fixture", () => {
    const mcp = loadOAuthProviderMcpConfig("box", providersDir);
    expect(mcp).toMatchObject({
      type: "remote",
      url: "https://mcp.box.com",
      transport: "http",
      headerMapping: { Authorization: "Bearer {{accessToken}}" },
    });
  });

  test("loads remote mcp_config from gusto fixture", () => {
    const mcp = loadOAuthProviderMcpConfig("gusto", providersDir);
    expect(mcp).toMatchObject({
      type: "remote",
      url: "https://mcp.api.gusto.com/",
      transport: "http",
    });
  });

  test("maps headerMapping accessToken placeholders to delivery {{token}}", () => {
    const delivery = mcpConfigToTemplateDelivery({
      type: "remote",
      url: "https://mcp.example.com/",
      transport: "http",
      headerMapping: { Authorization: "Bearer {{accessToken}}" },
    });
    expect(delivery).toEqual({
      as: "mcp",
      url: "https://mcp.example.com/",
      transport: "http",
      headers: { Authorization: "Bearer {{token}}" },
    });
  });

  test("returns null for type none", () => {
    expect(mcpConfigToTemplateDelivery({ type: "none" })).toBeNull();
  });

  test("resolveMcpTemplateDelivery prefers provider fixture over stale manifest", () => {
    const resolved = resolveMcpTemplateDelivery(
      "gusto",
      {
        as: "mcp",
        url: "https://stale.example.com/",
        transport: "http",
        headers: { Authorization: "Bearer {{token}}" },
      },
      providersDir,
    );
    expect(resolved?.url).toBe("https://mcp.api.gusto.com/");
  });

  test("resolveMcpTemplateDelivery falls back to manifest when fixture has no remote mcp", () => {
    const manifest = {
      as: "mcp" as const,
      url: "https://only-in-manifest.example.com/",
      transport: "http" as const,
      headers: { Authorization: "Bearer {{token}}" },
    };
    expect(resolveMcpTemplateDelivery("jobber", manifest, providersDir)).toEqual(manifest);
  });

  test("oauthProviderMcpConfigHashFragment is stable for remote mcp fixtures", () => {
    const a = oauthProviderMcpConfigHashFragment("gusto", providersDir);
    const b = oauthProviderMcpConfigHashFragment("gusto", providersDir);
    expect(a).toContain("mcp.api.gusto.com");
    expect(a).toBe(b);
    expect(oauthProviderMcpConfigHashFragment("jobber", providersDir)).toContain('"type":"none"');
  });
});

