  dropboxDriveOAuthConfigured,
  startDropboxDriveOAuthAuthorize,
} from "../../services/dropbox-drive-connection";

const GOOGLE_MY_DRIVE_OAUTH_STATE_TTL_SECONDS = 15 * 60;
const BOX_DRIVE_OAUTH_STATE_TTL_SECONDS = 15 * 60;
const DROPBOX_DRIVE_OAUTH_STATE_TTL_SECONDS = 15 * 60;

.get("/drive-files/dropbox/status", requirePermission("files.view"), async (c) => {
  const user = await c.var.auth.getUser();
  const orgId = resolveTenantOrgIdForWrite();
  return c.json({
    configured: await dropboxDriveOAuthConfigured({ orgId, userId: user.id }),
  });
})
.get("/drive-files/dropbox/connect", requirePermission("files.view"), async (c) => {
  const user = await c.var.auth.getUser();
  const orgId = resolveTenantOrgIdForWrite();
  if (!(await dropboxDriveOAuthConfigured({ orgId, userId: user.id }))) {
    return c.json({ error: "Dropbox OAuth is not available for this organization." }, 503);
  }
  const returnTo = c.req.query("returnTo")?.trim() || "/files";
  const state = base64url(randomBytes(24));
  await cache.set(
    `dropbox_drive_oauth:${state}`,
    JSON.stringify({ userId: user.id, orgId, returnTo }),
    DROPBOX_DRIVE_OAUTH_STATE_TTL_SECONDS,
  );
  try {
    const redirectUri = `${getAppBaseUrl(c)}/api/drive-files/dropbox/callback`;
    const authUrl = await startDropboxDriveOAuthAuthorize({
      orgId,
      userId: user.id,
      redirectUri,
      state,
    });
    return c.redirect(authUrl);
  } catch (error) {
    c.var.logger.error(
      "[dropbox-drive] authorize failed",
      error instanceof Error ? error.message : error,
    );
    return c.json(
      { error: error instanceof Error ? error.message : "Could not start Dropbox connection" },
      503,
    );
  }
})
.get("/drive-files/dropbox/callback", async (c) => {
  const state = c.req.query("state")?.trim() || "";
  const code = c.req.query("code")?.trim() || "";
  const providerError = c.req.query("error")?.trim();
  const raw = state ? await cache.get(`dropbox_drive_oauth:${state}`) : null;
  if (state) await cache.delete(`dropbox_drive_oauth:${state}`);
  type DropboxOAuthState = { userId: string; orgId: string; returnTo: string };
  let payload: DropboxOAuthState | null = null;
  try {
    payload = raw ? (JSON.parse(String(raw)) as DropboxOAuthState) : null;
  } catch {
    payload = null;
  }
  const returnTo = payload?.returnTo || "/files";
  const redirectWith = (
    status: "connected" | "error",
    options?: { reason?: string; driveId?: string },
  ) => {
    const destination = new URL(returnTo, c.req.url);
    destination.searchParams.set("dropboxDrive", status);
    if (options?.reason) destination.searchParams.set("dropboxDriveReason", options.reason);
    if (status === "connected" && options?.driveId) {
      destination.searchParams.set("drive", options.driveId);
      destination.searchParams.delete("driveFolder");
      destination.searchParams.delete("place");
      destination.searchParams.delete("provider");
      destination.searchParams.delete("googleLocation");
      destination.searchParams.delete("file");
    }
    return c.redirect(`${destination.pathname}${destination.search}`);
  };
  if (providerError) return redirectWith("error", { reason: "provider_denied" });
  if (!code) return redirectWith("error", { reason: "missing_code" });
  if (!payload) return redirectWith("error", { reason: "expired_state" });
  try {
    const result = await completeDropboxDriveOAuth({
      orgId: payload.orgId,
      userId: payload.userId,
      code,
    });
    return redirectWith("connected", { driveId: result.drive.id });
  } catch (error) {
    c.var.logger.warn(
      "[dropbox-drive] OAuth callback failed",
      error instanceof Error ? error.message : error,
    );
    const reason =
      error instanceof Error && /account identity/i.test(error.message)
        ? "missing_identity"
        : "complete_failed";
    return redirectWith("error", { reason });
  }
})
