import type { DriveFileSummary } from "@web/components/files/file-preview-registry";
import type {
  GenesisFilePickerDrive,
  GenesisFilePickerSelection,
} from "@web/components/files/genesis-file-picker";
import { useDriveFilesQuery } from "@web/hooks/use-drive-files-query";
import type { ComposerReferenceOption } from "@web/lib/composer-reference";
import { buildDriveFilesCacheQueryKey } from "@web/lib/drive-files-cache";
import { isBoxFileDriveKind, isGoogleFileDriveKind } from "@web/lib/file-drive-kinds";
import { useMemo } from "react";

type ReferenceFilesResponse = {
  drives?: Array<
    GenesisFilePickerDrive & {
      connectionId?: string | null;
    }
  >;
  files?: DriveFileSummary[];
};

export function useComposerFileReferences(enabled: boolean): {
  options: ComposerReferenceOption[];
  selectionFor: (option: ComposerReferenceOption) => GenesisFilePickerSelection | null;
} {
  const cacheKey = useMemo(
    () =>
      buildDriveFilesCacheQueryKey({
        driveId: null,
        folderId: null,
        status: "active",
      }),
    [],
  );
  const { data: payload } = useDriveFilesQuery<ReferenceFilesResponse>({
    params: "filesOnly=1",
    cacheKey,
    enabled,
  });

  const driveById = useMemo(
    () => new Map((payload?.drives ?? []).map((drive) => [drive.id, drive])),
    [payload?.drives],
  );
  const options = useMemo<ComposerReferenceOption[]>(
    () =>
      (payload?.files ?? [])
        .filter((file) => file.kind !== "folder" && file.status === "active")
        .sort((left, right) => right.modifiedAt.localeCompare(left.modifiedAt))
        .map((file) => {
          const drive = driveById.get(file.driveId);
          // Drive display names already encode account email / Workspace domain.
          const locationLabel = drive?.name ?? "Files";
          return {
            id: file.id,
            type: "file",
            label: file.name,
            description: locationLabel,
            keywords: `${locationLabel} ${drive?.kind ?? ""} ${file.mimeType ?? ""}`,
            file: {
              driveId: file.driveId,
              kind: file.kind,
              mimeType: file.mimeType,
              provider: isGoogleFileDriveKind(drive?.kind)
                ? "google_drive"
                : isBoxFileDriveKind(drive?.kind)
                  ? "box"
                  : "genesis",
            },
          };
        }),
    [driveById, payload?.files],
  );

  return {
    options,
    selectionFor(option) {
      if (option.type !== "file" || !option.file) return null;
      return {
        id: option.id,
        driveId: option.file.driveId,
        name: option.label,
        mimeType: option.file.mimeType,
        provider: option.file.provider,
      };
    },
  };
}

