export type GenesisFilePickerDrive = {
  id: string;
  kind: string;
  name: string;
  fileCount: number;
  connectionId?: string | null;
  genesisCorpus?: "my_drive" | "team_drive" | null;
  googleCorpus?: "my_drive" | "shared_drive" | null;
};

type PickerResponse = {
  drives?: GenesisFilePickerDrive[];
  files?: DriveFileSummary[];
  parent?: DriveFileSummary | null;
  breadcrumbs?: Array<{ id: string; name: string }>;
  error?: string;
};

export type GenesisFilePickerSelection = {
  id: string;
  driveId: string;
  name: string;
  mimeType: string | null;
  provider: "genesis" | "google_drive" | "box";
};

export type GenesisFilePickerProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelect: (file: GenesisFilePickerSelection) => void;
  acceptedMimeTypes?: readonly string[];
  fixture?: {
    drives: GenesisFilePickerDrive[];
    files: DriveFileSummary[];
  };
};

function isAccepted(file: DriveFileSummary, acceptedMimeTypes?: readonly string[]): boolean {
  if (file.kind === "folder" || !acceptedMimeTypes?.length) return true;
  return acceptedMimeTypes.some((accepted) =>
    accepted.endsWith("/*")
      ? file.mimeType?.startsWith(accepted.slice(0, -1))
      : file.mimeType === accepted,
  );
}

function providerForDrive(
  drive: GenesisFilePickerDrive | undefined,
): "genesis" | "google_drive" | "box" {
  if (isGoogleFileDriveKind(drive?.kind)) return "google_drive";
  if (isBoxFileDriveKind(drive?.kind)) return "box";
  return "genesis";
}

export function GenesisFilePicker({
  open,
  onOpenChange,
  onSelect,
  acceptedMimeTypes,
  fixture,
}: GenesisFilePickerProps) {
  const [driveId, setDriveId] = useState<string | null>(null);
  const [folderId, setFolderId] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const cacheKey = useMemo(
    () =>
      buildDriveFilesCacheQueryKey({
        driveId,
        folderId,
        status: "active",
      }),
    [driveId, folderId],
  );
  const params = useMemo(() => {
    const next = new URLSearchParams();
    if (driveId) next.set("driveId", driveId);
    if (!driveId) next.set("filesOnly", "1");
    if (driveId && folderId) next.set("parentId", folderId);
    return next.toString();
  }, [driveId, folderId]);
  const fileQuery = useDriveFilesQuery<PickerResponse>({
    params,
    cacheKey,
    enabled: open && !fixture,
  });
  const payload = fixture
    ? { drives: fixture.drives, files: fixture.files, breadcrumbs: [] }
    : fileQuery.data;
  const drives = payload?.drives ?? [];
  const files = payload?.files ?? [];
  const breadcrumbs = payload?.breadcrumbs ?? [];
  const loading = !fixture && fileQuery.loading;
  const error = !fixture ? fileQuery.error : null;

  useEffect(() => {
    if (open) return;
    setDriveId(null);
    setFolderId(null);
    setQuery("");
    setSelectedId(null);
  }, [open]);

  const visibleFiles = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();
    return files
      .filter((file) => !normalizedQuery || file.name.toLowerCase().includes(normalizedQuery))
      .sort((a, b) => {
        if (a.kind === "folder" && b.kind !== "folder") return -1;
        if (a.kind !== "folder" && b.kind === "folder") return 1;
        return a.name.localeCompare(b.name);
      });
  }, [files, query]);
  const selectedFile = files.find((file) => file.id === selectedId) ?? null;
  const selectedDrive = drives.find((drive) => drive.id === driveId);
  const aggregateFileCount = drives.reduce((total, drive) => total + drive.fileCount, 0);
  const genesisDrives = drives.filter((drive) => isGenesisFileDriveKind(drive.kind));
  const genesisMyDrive = genesisDrives.find((drive) => drive.genesisCorpus === "my_drive") ?? null;
  const genesisTeamDrive =
    genesisDrives.find((drive) => drive.genesisCorpus === "team_drive") ?? null;
  const ungroupedGenesisDrives = genesisDrives.filter(
    (drive) => drive !== genesisMyDrive && drive !== genesisTeamDrive,
  );
  const googleDrives = drives.filter((drive) => isGoogleFileDriveKind(drive.kind));
  const boxDrives = drives.filter((drive) => isBoxFileDriveKind(drive.kind));
  const googleMyDriveMounts = googleDrives.filter((drive) => isGoogleMyDriveKind(drive.kind));
  const workspaceDrives = googleDrives.filter((drive) => isGoogleWorkspaceDriveKind(drive.kind));
  const workspaceConnectionGroups = useMemo(() => {
    const byConnection = new Map<
      string,
      {
        connectionId: string;
        label: string;
        myDrive: GenesisFilePickerDrive | null;
        shared: GenesisFilePickerDrive[];
      }
    >();
    for (const drive of workspaceDrives) {
      const connectionId = drive.connectionId?.trim() || drive.id;
      const existing = byConnection.get(connectionId) ?? {
        connectionId,
        label: drive.name.replace(/\s·\sMy Drive$/, "") || "Google Workspace Drive",
        myDrive: null,
        shared: [],
      };
      if (drive.googleCorpus === "shared_drive") {
        existing.shared.push(drive);
      } else {
        existing.myDrive = drive;
        existing.label = drive.name.replace(/\s·\sMy Drive$/, "") || existing.label;
      }
      byConnection.set(connectionId, existing);
    }
    return [...byConnection.values()].sort((a, b) => a.label.localeCompare(b.label));
  }, [workspaceDrives]);

  const chooseDrive = (nextDriveId: string | null) => {
    setDriveId(nextDriveId);
    setFolderId(null);
    setSelectedId(null);
  };

  const openFolder = (file: DriveFileSummary) => {
    setDriveId(file.driveId);
    setFolderId(file.id);
    setSelectedId(null);
  };

  const confirmSelection = () => {
    if (!selectedFile || selectedFile.kind === "folder") return;
    onSelect({
      id: selectedFile.id,
      driveId: selectedFile.driveId,
      name: selectedFile.name,
      mimeType: selectedFile.mimeType,
      provider: providerForDrive(drives.find((drive) => drive.id === selectedFile.driveId)),
    });
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="flex h-[min(44rem,calc(100svh-2rem))] w-[calc(100vw-2rem)] !max-w-5xl flex-col gap-0 overflow-hidden p-0"
        onOpenAutoFocus={(event) => {
          event.preventDefault();
          searchInputRef.current?.focus();
        }}
      >
        <DialogHeader className="border-b border-border px-5 py-4">
          <DialogTitle>Choose a file</DialogTitle>
          <DialogDescription>Select a file from any drive connected to Genesis.</DialogDescription>
