            <nav className="p-4" aria-label="File locations">
              <p className="px-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">
                Places
              </p>
              <button
                type="button"
                className={cn(
                  "mt-2 flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-left text-sm hover:bg-muted/50 hover:text-foreground",
                  driveId === null
                    ? "bg-muted/70 font-medium text-foreground"
                    : "text-muted-foreground",
                )}
                onClick={() => chooseDrive(null)}
              >
                <Files className="size-4" />
                <span className="min-w-0 flex-1 truncate">All files</span>
                <SidebarCountPill
                  value={aggregateFileCount}
                  className="border-border bg-background text-muted-foreground"
                />
              </button>

              <div className="mt-6 border-t border-border pt-4">
