                              </span>
                              <SidebarCountPill
                                value={drive.fileCount}
                                className="border-border bg-background text-muted-foreground"
                              />
                            </button>
                          ))}
                      </div>
                    </div>
                  ) : null}

                  {googleMyDriveMounts.map((drive) => {
                    const { title, account } = splitGoogleMyDriveLabel(drive.name);
                    return (
                      <div
                        key={drive.id}
                        className={cn("rounded-sm", drive.id === driveId && "bg-muted/70")}
                      >
                        <button
                          type="button"
                          className={cn(
                            "flex w-full items-center gap-2 rounded-sm px-2 py-2 text-left text-sm",
                            drive.id === driveId
                              ? "font-medium text-foreground"
                              : "text-muted-foreground hover:bg-muted/50 hover:text-foreground",
                          )}
                          onClick={() => chooseDrive(drive.id)}
                        >
                          <span className="grid size-7 shrink-0 place-items-center rounded-sm bg-background shadow-sm">
                            <img src="/google-drive.svg" alt="" className="size-[18px]" />
