import { googleResumableContentRange, googleResumableNextOffset } from "./google-resumable-upload";

type BatchState = {
  canceled: boolean;
  controllers: Set<AbortController>;
  /** Absolute origin of the app page that started this batch (not the CDN). */
  appOrigin: string;
};

/** Resolve app API paths. Blob-backed workers have no document base URL. */
function appApiUrl(appOrigin: string, path: string): string {
  return new URL(path, appOrigin.endsWith("/") ? appOrigin : `${appOrigin}/`).href;
}

type PreparedUpload = {
  strategy: "s3_presigned_put" | "google_resumable" | "api_relay";
  /** Server-resolved unique name (may differ from File.name on collision). */
  name: string;
  uploadId?: string;
  uploadUrl: string;
  headers: Record<string, string>;
};

const batches = new Map<string, BatchState>();

function post(message: DriveFileUploadWorkerOutbound): void {
  self.postMessage(message);
}

async function waitForRetry(delayMs: number, batch: BatchState): Promise<void> {
  const deadline = Date.now() + delayMs;
  while (!batch.canceled && Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, Math.min(100, deadline - Date.now())));
  }
}

async function fetchForBatch(
  batch: BatchState,
  input: RequestInfo | URL,
  init: RequestInit,
): Promise<Response> {
  if (batch.canceled) throw new DOMException("Upload canceled", "AbortError");
  const controller = new AbortController();
  batch.controllers.add(controller);
  try {
    return await fetch(input, { ...init, signal: controller.signal });
  } finally {
    batch.controllers.delete(controller);
  }
}

async function responsePayload<T>(response: Response): Promise<T & { error?: string }> {
  return response.json().catch(() => ({})) as Promise<T & { error?: string }>;
}

async function requestWithRetries<T>(
  batch: BatchState,
  request: () => Promise<Response>,
  read: (response: Response) => Promise<T & { error?: string }>,
  fallbackMessage: string,
  maxAttempts = DRIVE_FILE_UPLOAD_MAX_ATTEMPTS,
): Promise<T> {
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    let response: Response;
    try {
      response = await request();
    } catch (error) {
      if (
        batch.canceled ||
        (error instanceof DOMException && error.name === "AbortError") ||
        attempt >= maxAttempts
      ) {
        throw error;
      }
      await waitForRetry(driveFileUploadRetryDelayMs(attempt), batch);
      continue;
    }
    const payload = await read(response);
    if (response.ok) return payload;
    const message = payload.error || fallbackMessage;
    if (attempt >= maxAttempts || !isRetryableDriveFileUploadResponse(response.status, message)) {
      throw new Error(message);
    }
    await waitForRetry(driveFileUploadRetryDelayMs(attempt), batch);
  }
  throw new Error(fallbackMessage);
}

async function googleUploadResultFromStatus(
  file: File,
  prepared: PreparedUpload,
  batch: BatchState,
): Promise<{ fileId: string | null; nextOffset: number } | null> {
  const response = await fetchForBatch(batch, prepared.uploadUrl, {
    method: "PUT",
    headers: { "Content-Range": `bytes */${file.size}` },
  });
  if (response.status === 308) {
    return { fileId: null, nextOffset: googleResumableNextOffset(response.headers.get("Range")) };
  }
  if (!response.ok) return null;
  const metadata = (await response.json().catch(() => null)) as { id?: string } | null;
  return { fileId: metadata?.id ?? null, nextOffset: file.size };
}

