} from "@web/lib/query-mutations";

export class FileMutationError extends Error {
  readonly actionUrl?: string;

  constructor(message: string, actionUrl?: string) {
    super(message);
    this.name = "FileMutationError";
    this.actionUrl = actionUrl;
  }
}

export type FileReferenceInput = {
  providerFileId: string;
  name: string;
  mimeType: string;
  provider?: "notion" | "google_drive" | string;
};

export type FileReferenceResponse = {
  file: FileRecord;
  providerMetadata?: { name?: string; mimeType?: string | null };
  driveMetadata?: { name?: string; mimeType?: string | null; size?: string };
};

export type UploadFileInput = {
  file: globalThis.File;
  parentFolderPath?: string;
};

export type UploadFileResult = {
  file?: FileRecord;
  folderPath?: string;
  providerFile?: {
    id: string;
    name: string;
    mimeType: string;
    size?: string;
    modifiedTime?: string;
  };
};

export type CreateFileInput = {
  type: "folder" | "markdown" | "google_doc" | "google_sheet" | "google_slide";
  name?: string;
  parentFolderPath?: string;
};

export type CreateFileResult = {
  file?: FileRecord;
  folderPath?: string;
  activationUrl?: string;
  error?: string;
  message?: string;
};

/** Prefix match — files list keys include viewerKey. */
const FILES_LIST_INVALIDATE = [["files", "list"] as const];

function parseApiErrorPayload(text: string): {
  message?: string;
  error?: string;
  activationUrl?: string;
} | null {
  try {
    return JSON.parse(text) as {
      message?: string;
      error?: string;
      activationUrl?: string;
    };
  } catch {
    return null;
  }
}

function googleDriveDisabledMessage(kind: "upload" | "create"): string {
  return kind === "upload"
    ? "Google Drive API is disabled for this Google Cloud project. Enable it, wait a few minutes, then retry the upload."
    : "Google Drive API is disabled for this Google Cloud project. Enable it, wait a few minutes, then retry document creation.";
}

export function toFileMutationError(
  err: unknown,
  fallback: string,
  kind?: "upload" | "create",
): never {
  if (err instanceof FileMutationError) throw err;
  if (err instanceof QueryFetchError) {
    const data = parseApiErrorPayload(err.message);
    if (data?.error === "google_drive_api_disabled") {
      throw new FileMutationError(googleDriveDisabledMessage(kind ?? "upload"), data.activationUrl);
    }
    throw new FileMutationError(
      data?.message || data?.error || err.message || fallback,
      data?.activationUrl,
    );
  }
  if (err && typeof err === "object" && "message" in err && typeof err.message === "string") {
    throw new FileMutationError(err.message);
  }
  throw new FileMutationError(fallback);
}

