  return postJson("/api/drive-files/reference", { driveId, providerObjectId });
}

export async function uploadFileApi(input: UploadFileInput): Promise<UploadFileResult> {
  const formData = new FormData();
  formData.append("file", input.file);
  if (input.parentFolderPath) formData.append("parentFolderPath", input.parentFolderPath);
  try {
    return await postFormData<UploadFileResult>("/api/files/upload", formData);
  } catch (err) {
    toFileMutationError(err, "Upload failed. Please try again.", "upload");
