function DriveProviderIcon({
  kind,
  className = "size-4",
}: {
  kind: string | null | undefined;
  className?: string;
}) {
  if (isGoogleFileDriveKind(kind)) {
    return <img src="/google-drive.svg" alt="" className={className} />;
  }
  if (isBoxFileDriveKind(kind)) {
    return <img src="/box.svg" alt="" className={cn(className, "object-contain")} />;
  }
  return <GenesisIcon className={className} />;
}

function DriveRootBreadcrumb({ drive }: { drive: DriveSummary | null }) {
  if (drive?.googleCorpus === "shared_drive") {
    return (
      <>
        <img src="/google-drive.svg" alt="" className="size-3.5 shrink-0" />
        <span className="truncate">{drive.name}</span>
      </>
    );
  }
  return (
    <span className="truncate">
      {drive ? (isGoogleMyDriveKind(drive.kind) ? "My Drive" : drive.name) : "All files"}
    </span>
  );
}

function FileGridPreview({ file }: { file: DriveFileSummary }) {
  if (file.kind === "folder") return <Folder className="size-8 text-amber-600" />;
  // SVG is served as attachment + CSP sandbox; grid <img> cannot load it reliably.
  const isSvg =
    file.mimeType?.split(";", 1)[0]?.trim().toLowerCase() === "image/svg+xml" ||
    /\.svg$/i.test(file.name);
  if (file.status === "active" && file.mimeType?.startsWith("image/") && !isSvg) {
    return (
      <img
        src={`/api/drive-files/${encodeURIComponent(file.id)}/content`}
