/**
 * User-managed MCP server slugs. Shared by server create and Settings UI so
 * reserved broker/capability ids (linear, notion, …) auto-map to safe slugs.
 *
 * Skill gate: genesis-integration-oauth-configure § 5b (B2) and
 * genesis-integration workflow step "MCP catalog map + reserved user MCP slug".
 * When you add a broker / connection-capability slug, add it here in the same
 * change (and keep CONNECTION_CAPABILITY_TEMPLATE_SLUGS aligned when a template
 * package exists).
 */

/** Built-in connection / capability slugs that must not collide in MCP_SERVERS. */
export const USER_MCP_RESERVED_SLUGS = new Set<string>([
  "google",
  "box",
  "notion",
  "github",
  "linear",
  "slack",
  "attio",
  "hubspot",
  "salesforce",
  "sage",
  "todoist",
  "mercury",
  "gusto",
  "wave",
  "xero",
  "jobber",
  "quickbooks",
  "printavo",
  "shopmonkey",
  "callrail",
  "calcom",
  "spotify",
  "meta",
  "apollo",
  "google-business",
  "genesis",
  "secret",
  "custom",
]);

const SLUG_PATTERN = /^[a-z][a-z0-9_-]{0,47}$/;

/**
 * When a slug collides with a built-in connection (e.g. linear), auto-suffix
 * so Settings / agents can still add a user MCP without a reserved-slug error.
 */
export function allocateNonReservedUserMcpSlug(base: string): string {
  const cleaned = base
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
  if (cleaned && SLUG_PATTERN.test(cleaned) && !USER_MCP_RESERVED_SLUGS.has(cleaned)) {
    return cleaned;
  }
  const stem = (cleaned && SLUG_PATTERN.test(cleaned) ? cleaned : "mcp").slice(0, 40);
  const withMcp = `${stem}_mcp`.slice(0, 48);
  if (SLUG_PATTERN.test(withMcp) && !USER_MCP_RESERVED_SLUGS.has(withMcp)) {
    return withMcp;
  }
  for (let i = 2; i <= 20; i++) {
    const candidate = `${stem.slice(0, 40)}_mcp${i}`.slice(0, 48);
    if (SLUG_PATTERN.test(candidate) && !USER_MCP_RESERVED_SLUGS.has(candidate)) {
      return candidate;
    }
  }
  // Browser-safe fallback (no node crypto).
  const rand = Math.random().toString(36).slice(2, 10);
  return `mcp_${rand}`;
}

export function normalizeUserMcpSlug(raw: string | undefined, displayName: string): string {
  const fromInput = raw?.trim().toLowerCase() ?? "";
  if (fromInput) {
    const cleaned = fromInput
      .replace(/[^a-z0-9_-]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 48);
    if (!cleaned || !SLUG_PATTERN.test(cleaned)) {
      throw new Error(
        "Use a slug like acme_tools: start with a letter, then letters, numbers, _ or -.",
      );
    }
    return allocateNonReservedUserMcpSlug(cleaned);
  }
  const fromName = displayName
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .replace(/_+/g, "_")
    .slice(0, 48);
  if (fromName && SLUG_PATTERN.test(fromName)) {
    return allocateNonReservedUserMcpSlug(fromName);
  }
  return allocateNonReservedUserMcpSlug(`mcp_${Math.random().toString(36).slice(2, 10)}`);
}

import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, test } from "vitest";
import {
  loadOAuthProviderMcpConfig,
  mcpConfigToTemplateDelivery,
  oauthProviderMcpConfigHashFragment,
  resolveMcpTemplateDelivery,
  resolveOAuthProvidersDir,
} from "./oauth-provider-mcp-delivery";

const monorepoWebRoot = join(dirname(fileURLToPath(import.meta.url)), "../..");
const providersDir = join(monorepoWebRoot, "tools/genesis/oauth-providers");

describe("oauth-provider-mcp-delivery", () => {
  test("resolveOAuthProvidersDir finds fixtures from apps/web cwd", () => {
    expect(resolveOAuthProvidersDir(monorepoWebRoot)).toBe(providersDir);
  });

  test("loads remote mcp_config from the Box fixture", () => {
    const mcp = loadOAuthProviderMcpConfig("box", providersDir);
    expect(mcp).toMatchObject({
      type: "remote",
      url: "https://mcp.box.com",
      transport: "http",
      headerMapping: { Authorization: "Bearer {{accessToken}}" },
    });
  });

  test("loads remote mcp_config from gusto fixture", () => {
    const mcp = loadOAuthProviderMcpConfig("gusto", providersDir);
    expect(mcp).toMatchObject({
      type: "remote",
      url: "https://mcp.api.gusto.com/",
      transport: "http",
    });
  });

  test("maps headerMapping accessToken placeholders to delivery {{token}}", () => {
    const delivery = mcpConfigToTemplateDelivery({
      type: "remote",
      url: "https://mcp.example.com/",
      transport: "http",
      headerMapping: { Authorization: "Bearer {{accessToken}}" },
    });
    expect(delivery).toEqual({
      as: "mcp",
      url: "https://mcp.example.com/",
      transport: "http",
      headers: { Authorization: "Bearer {{token}}" },
    });
  });

  test("returns null for type none", () => {
    expect(mcpConfigToTemplateDelivery({ type: "none" })).toBeNull();
  });

  test("resolveMcpTemplateDelivery prefers provider fixture over stale manifest", () => {
    const resolved = resolveMcpTemplateDelivery(
      "gusto",
      {
        as: "mcp",
        url: "https://stale.example.com/",
        transport: "http",
        headers: { Authorization: "Bearer {{token}}" },
      },
      providersDir,
    );
    expect(resolved?.url).toBe("https://mcp.api.gusto.com/");
  });

  test("resolveMcpTemplateDelivery falls back to manifest when fixture has no remote mcp", () => {
    const manifest = {
      as: "mcp" as const,
      url: "https://only-in-manifest.example.com/",
      transport: "http" as const,
      headers: { Authorization: "Bearer {{token}}" },
    };
    expect(resolveMcpTemplateDelivery("jobber", manifest, providersDir)).toEqual(manifest);
  });

  test("oauthProviderMcpConfigHashFragment is stable for remote mcp fixtures", () => {
    const a = oauthProviderMcpConfigHashFragment("gusto", providersDir);
    const b = oauthProviderMcpConfigHashFragment("gusto", providersDir);
    expect(a).toContain("mcp.api.gusto.com");
    expect(a).toBe(b);
    expect(oauthProviderMcpConfigHashFragment("jobber", providersDir)).toContain('"type":"none"');
  });
});

