/**
 * Detect when a public MCP catalog entry overlaps a Genesis Third Party
 * (broker) integration — so Settings can warn before a second connect path.
 */

export type NativeIntegrationForMcpOverlap = {
  id: string;
  name: string;
  connected: boolean;
  /** Collections / bidirectional sync when Genesis supports it for this provider. */
  syncCapable?: boolean;
};

export type McpCatalogHitForOverlap = {
  domain: string;
  name: string;
  slug?: string | null;
};

export type UserMcpNativeOverlap = {
  integrationId: string;
  integrationName: string;
  connected: boolean;
  syncCapable: boolean;
};

/**
 * Known public MCP catalog domains (integrations.sh style) → Genesis broker
 * integration id. Keep this table current when shipping a new Third Party app
 * that also appears in the public MCP catalog.
 *
 * Skill gate: genesis-integration-oauth-configure § 5b and genesis-integration
 * workflow step "MCP catalog ↔ Third Party mapping". Extend tests when you add
 * rows.
 */
export const MCP_CATALOG_DOMAIN_TO_INTEGRATION_ID: Readonly<Record<string, string>> = {
  "box.com": "box",
  "mcp.box.com": "box",
  "linear.app": "linear",
  "mcp.linear.app": "linear",
  "notion.so": "notion",
  "notion.com": "notion",
  // Official Notion MCP marketing / developer hosts on integrations.sh
  "makenotion.com": "notion",
  "mcp.notion.com": "notion",
  // integrations.sh discovered Notion doc/site hosts (same product, different domains)
  "notion.notion.site": "notion",
  "notiondevs.notion.site": "notion",
  "github.com": "github",
  "hubspot.com": "hubspot",
  "mcp.hubspot.com": "hubspot",
  "slack.com": "slack",
  "attio.com": "attio",
  "mcp.attio.com": "attio",
  "mercury.com": "mercury",
  "mcp.mercury.com": "mercury",
  "cal.com": "calcom",
  "mcp.cal.com": "calcom",
  "gusto.com": "gusto",
  "mcp.api.gusto.com": "gusto",
  "todoist.com": "todoist",
  "salesforce.com": "salesforce",
  "xero.com": "xero",
  "waveapps.com": "wave",
  "wave.com": "wave",
  "getjobber.com": "jobber",
  "jobber.com": "jobber",
  "quickbooks.intuit.com": "quickbooks",
  "intuit.com": "quickbooks",
  "spotify.com": "spotify",
  "apollo.io": "apollo",
  "mcp.apollo.io": "apollo",
  "meta.com": "meta",
  "facebook.com": "meta",
  "google.com": "google",
  "workspace.google.com": "google",
};

/** Broker integration ids we know from the catalog domain map (for product collapse). */
const KNOWN_INTEGRATION_IDS_FROM_CATALOG_MAP: ReadonlySet<string> = new Set(
  Object.values(MCP_CATALOG_DOMAIN_TO_INTEGRATION_ID),
);

function normalizeToken(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "");
}

/**
 * Product name/slug match beyond exact equality.
 * Catches "Notion MCP", "notion-mcp", "mcp-notion" without matching "metadata" to "meta".
 */
export function mcpCatalogProductTokensMatch(hitLabel: string, product: string): boolean {
  const hit = normalizeToken(hitLabel);
  const productToken = normalizeToken(product);
  if (hit.length < 3 || productToken.length < 3) return false;
  if (hit === productToken) return true;

  // Require a product token long enough to avoid short false positives (meta→metadata).
  if (productToken.length < 4) return false;

  const restPrefix = hit.startsWith(productToken) ? hit.slice(productToken.length) : null;
  if (restPrefix !== null) {
    // notionmcp, notionserver, notionai…
    if (restPrefix === "" || /^(mcp|server|ai|api|app|hq|inc|io|com|so)/.test(restPrefix)) {
      return true;
    }
  }

  const restSuffix = hit.endsWith(productToken) ? hit.slice(0, -productToken.length) : null;
  if (restSuffix !== null) {
    // mcpnotion, servernotion, makenotion…
    if (restSuffix === "" || /(mcp|server|ai|api|app|hq|inc|make|get)$/.test(restSuffix)) {
      return true;
    }
  }

  return false;
}

/**
 * Stable product key for catalog-to-catalog collapse (and native merge).
 * Maps makenotion.com / notion.so / notion.notion.site → "notion".
 * Returns null when the hit is not a known multi-host product.
 */
export function mcpCatalogProductKey(hit: McpCatalogHitForOverlap): string | null {
  const domainHint = integrationIdHintFromMcpDomain(hit.domain);
  if (domainHint && KNOWN_INTEGRATION_IDS_FROM_CATALOG_MAP.has(domainHint)) {
    return domainHint;
  }

  // Soft second-level host label already returned above when it is a known id.
  // Also match name/slug tokens against known products (e.g. "Notion MCP").
  const labels = [hit.slug?.trim() ?? "", hit.name?.trim() ?? ""].filter(Boolean);
  for (const id of KNOWN_INTEGRATION_IDS_FROM_CATALOG_MAP) {
    for (const label of labels) {
      if (mcpCatalogProductTokensMatch(label, id)) return id;
    }
  }

  return null;
}

/**
 * Single coverage decision for a public MCP catalog hit.
 * Prefer a Genesis native when present; otherwise collapse known multi-host
 * products; otherwise treat the hit as unique.
 */
export type McpCatalogHitCoverage =
  | { kind: "native"; integrationId: string }
  | { kind: "product"; productKey: string }
  | { kind: "unique" };

export function coverMcpCatalogHit(
  hit: McpCatalogHitForOverlap,
  integrations: readonly NativeIntegrationForMcpOverlap[],
): McpCatalogHitCoverage {
  const native = matchNativeIntegrationForMcpCatalogHit(hit, integrations);
  if (native) {
    return { kind: "native", integrationId: native.integrationId };
  }

  const productKey = mcpCatalogProductKey(hit);
  if (productKey) {
    const byId = new Map(integrations.map((row) => [row.id.toLowerCase(), row]));
    const nativeByProduct = byId.get(productKey.toLowerCase());
    if (nativeByProduct) {
      return { kind: "native", integrationId: nativeByProduct.id };
    }
    return { kind: "product", productKey };
  }

