export type SessionAttachmentSource = "temporary" | "workspace" | "drive" | "notion";

export type SessionAttachmentProvider =
  | "genesis"
  | "google_drive"
  | "notion"
  | "box"
  | "dropbox";

/** Safe attachment identity that can live in the durable session transcript. */
export interface SessionAttachmentMetadata {
  name: string;
  mimeType: string;
  source: SessionAttachmentSource;
  previewAvailable: boolean;
  size?: number;
  workspacePath?: string;
  driveFileId?: string;
  fileReferenceId?: string;
  provider?: SessionAttachmentProvider;
  providerFileId?: string;
  previewMimeType?: string;
}

const MAX_SESSION_MESSAGE_ATTACHMENTS = 20;
const MAX_ATTACHMENT_FIELD_LENGTH = 2_048;

function optionalString(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  if (!trimmed || trimmed.length > MAX_ATTACHMENT_FIELD_LENGTH) return undefined;
  return trimmed;
}

export function normalizeSessionAttachmentWorkspacePath(value: unknown): string | undefined {
  const path = optionalString(value)?.replace(/^\/+/, "");
  if (!path || path.includes("\\")) return undefined;
  const segments = path.split("/");
  if (segments.some((segment) => segment === "" || segment === "." || segment === "..")) {
    return undefined;
  }
  return path;
}

function isAttachmentSource(value: unknown): value is SessionAttachmentSource {
  return value === "temporary" || value === "workspace" || value === "drive" || value === "notion";
}

function isAttachmentProvider(value: unknown): value is SessionAttachmentProvider {
  return value === "genesis" || value === "google_drive" || value === "notion" || value === "box";
}

export function parseSessionAttachmentMetadata(value: unknown): SessionAttachmentMetadata[] {
  if (!Array.isArray(value)) return [];

  const files: SessionAttachmentMetadata[] = [];
  for (const item of value.slice(0, MAX_SESSION_MESSAGE_ATTACHMENTS)) {
    if (!item || typeof item !== "object" || Array.isArray(item)) continue;
    const record = item as Record<string, unknown>;
    const name = optionalString(record.name);
    const mimeType = optionalString(record.mimeType);
    if (!name || !mimeType || !isAttachmentSource(record.source)) continue;

    const workspacePath = normalizeSessionAttachmentWorkspacePath(record.workspacePath);
    const driveFileId = optionalString(record.driveFileId);
    const fileReferenceId = optionalString(record.fileReferenceId);
    const providerFileId = optionalString(record.providerFileId);
    const previewMimeType = optionalString(record.previewMimeType);
    const provider = isAttachmentProvider(record.provider) ? record.provider : undefined;
    const size =
      typeof record.size === "number" && Number.isFinite(record.size) && record.size >= 0
        ? record.size
        : undefined;

    files.push({
      name,
      mimeType,
      source: record.source,
      previewAvailable: Boolean(
        workspacePath || driveFileId || fileReferenceId || (provider && providerFileId),
      ),
      ...(size !== undefined ? { size } : {}),
      ...(workspacePath ? { workspacePath } : {}),
      ...(driveFileId ? { driveFileId } : {}),
      ...(fileReferenceId ? { fileReferenceId } : {}),
      ...(provider ? { provider } : {}),
      ...(providerFileId ? { providerFileId } : {}),
      ...(previewMimeType ? { previewMimeType } : {}),
    });
  }
  return files;
}

