  const legacyIds = ids.filter((id) => !canonicalIds.has(id));
  const legacyRefs =
    legacyIds.length === 0
      ? []
      : await db
          .select({
            id: fileReference.id,
            name: fileReference.name,
            provider: fileReference.provider,
            providerFileId: fileReference.providerFileId,
            mimeType: fileReference.mimeType,
          })
          .from(fileReference)
          .where(
            and(
              inArray(fileReference.id, legacyIds),
              eq(fileReference.userId, userId),
              eq(fileReference.orgId, tenantOrgId),
            ),
          );
  const refsById = new Map<string, AuthorizedFileReference>([
    ...canonicalRefs.map(
      (ref) =>
        [
          ref.id,
          {
            ...ref,
            provider:
              ref.provider === "box"
                ? "box"
                : ref.provider === "google_drive" ||
                    ref.provider === "google_my_drive" ||
                    ref.provider === "google_workspace_drive"
                  ? "google_drive"
                  : "genesis",
            locatorKind: ref.locatorKind as AuthorizedFileReference["locatorKind"],
            scopeType: ref.scopeType as AuthorizedFileReference["scopeType"],
          },
        ] as const,
    ),
    ...legacyRefs.map((ref) => [ref.id, ref] as const),
  ]);
  return ids.flatMap((id) => {
    const ref = refsById.get(id);
    return ref ? [ref] : [];
  });
}

