import { describe, expect, test } from "vitest";
import { USER_MCP_RESERVED_SLUGS } from "../domain/user-mcp-slug";
import { CONNECTION_CAPABILITY_TEMPLATE_SLUGS } from "./connection-capability-sync";
import {
  assertUserMcpServerUrl,
  findUserMcpSecretOwnerBinding,
  materializeUserMcpSecretHeader,
  mergeUserMcpServersIntoEnv,
  normalizeCachedToolNames,
  normalizeUserMcpHeaderAuth,
  normalizeUserMcpSlug,
  statusAfterUserMcpHeaderAuth,
} from "./user-mcp-servers";

describe("user MCP servers", () => {
  test("normalizes slug from display name", () => {
    expect(normalizeUserMcpSlug(undefined, "Acme Tools")).toBe("acme_tools");
  });

  test("auto-renames reserved broker slugs so catalog add still works", () => {
    const reserved = "linear";
    expect(USER_MCP_RESERVED_SLUGS.has(reserved)).toBe(true);
    const slug = normalizeUserMcpSlug(reserved, "x");
    expect(slug).toBe("linear_mcp");
    expect(USER_MCP_RESERVED_SLUGS.has(slug)).toBe(false);
  });

  test("maps built-in integration slugs to non-reserved user MCP slugs", () => {
    expect(normalizeUserMcpSlug("box", "Box")).toBe("box_mcp");
    expect(normalizeUserMcpSlug("linear", "Linear")).toBe("linear_mcp");
  });

  test("requires HTTPS except localhost HTTP", () => {
    expect(assertUserMcpServerUrl("https://mcp.example.com/mcp")).toContain("https://");
    expect(assertUserMcpServerUrl("http://127.0.0.1:3100/mcp")).toContain("127.0.0.1");
    expect(() => assertUserMcpServerUrl("http://example.com/mcp")).toThrow(/HTTPS/);
    expect(() => assertUserMcpServerUrl("https://user:pass@example.com/mcp")).toThrow(
      /credentials/,
    );
  });

  test("merge leaves broker keys untouched", () => {
    const merged = mergeUserMcpServersIntoEnv(
      JSON.stringify({ linear: { url: "https://broker" } }),
      {
        linear: { url: "https://user-override" },
        acme: { url: "https://acme" },
      },
    );
    const parsed = JSON.parse(merged!) as Record<string, { url: string } | undefined>;
    expect(parsed.linear?.url).toBe("https://broker");
    expect(parsed.acme?.url).toBe("https://acme");
  });

  test("normalizeCachedToolNames de-dupes and caps", () => {
    expect(normalizeCachedToolNames(["echo", " echo ", "list", 1, ""])).toEqual(["echo", "list"]);
  });

  test("preserves a raw custom authentication header", () => {
    expect(
      normalizeUserMcpHeaderAuth({
        headerName: "x-openstatus-key",
        headerTemplate: "{{secret}}",
      }),
    ).toEqual({ headerName: "x-openstatus-key", headerTemplate: "{{secret}}" });
  });

  test("materializes a custom header without a Bearer prefix", () => {
    expect(
      materializeUserMcpSecretHeader(
        { headerName: "x-openstatus-key", headerTemplate: "{{secret}}" },
        "test-key",
      ),
    ).toEqual({ "x-openstatus-key": "test-key" });
  });

  test("keeps a disabled server disabled after an access key update", () => {
    expect(statusAfterUserMcpHeaderAuth("disabled")).toBe("disabled");
    expect(statusAfterUserMcpHeaderAuth("error")).toBe("active");
  });

  test("finds the owning revoked Secrets binding instead of a newer consumer", () => {
    const owner = {
      id: "binding:custom:secret_1:api_key",
      capabilityId: "custom:secret_1",
      requirementName: "api_key",
      status: "revoked" as const,
      scope: { kind: "user" as const, id: "user_1" },
      value: { kind: "secret" as const, secretRef: "custom/secret_1/api_key" },
    };
    const consumer = {
      ...owner,
      id: "binding:consumer:provider_key",
      capabilityId: "consumer",
      requirementName: "provider_key",
    };
    expect(findUserMcpSecretOwnerBinding([consumer, owner], "custom/secret_1/api_key")).toBe(owner);
    expect(findUserMcpSecretOwnerBinding([consumer], "custom/secret_1/api_key")).toBeNull();
  });

  test("rejects unsafe headers and malformed templates", () => {
    expect(() =>
      normalizeUserMcpHeaderAuth({ headerName: "Host", headerTemplate: "{{secret}}" }),
    ).toThrow(/header name/i);
    expect(() =>
      normalizeUserMcpHeaderAuth({
        headerName: "x-api-key",
        headerTemplate: "{{secret}}\r\nHost: example.com",
      }),
    ).toThrow(/include the access key/i);
    expect(() =>
      normalizeUserMcpHeaderAuth({
        headerName: "x-api-key",
        headerTemplate: "{{secret}}-{{secret}}",
      }),
    ).toThrow(/include the access key/i);
  });

  test("every connection-capability template slug is reserved for user MCP", () => {
    for (const slug of CONNECTION_CAPABILITY_TEMPLATE_SLUGS) {
      expect(
        USER_MCP_RESERVED_SLUGS.has(slug),
        `USER_MCP_RESERVED_SLUGS must include template slug "${slug}"`,
      ).toBe(true);
    }
  });
});

