import type { OAuthConnection, ProviderIdentity, TokenBundle } from "../types";
import { fetchWithTimeout, firstNonEmpty, objectClaim, readJson, stringClaim } from "./util";

export const dropboxConfig = {
  currentAccountUrl: "https://api.dropboxapi.com/2/users/get_current_account",
};

export async function dropboxIdentity(
  _connection: OAuthConnection,
  accessToken: string,
  _token: TokenBundle,
): Promise<ProviderIdentity> {
  const response = await fetchWithTimeout(dropboxConfig.currentAccountUrl, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: "application/json",
      "Content-Type": "application/json",
    },
    body: "{}",
  });
  const profile = await readJson(response);
  if (!response.ok) {
    throw Object.assign(new Error(`dropbox account identity failed: ${response.status}`), {
      status: 502,
      details: profile,
      upstream_status: response.status,
    });
  }

  const accountId = stringClaim(profile, "account_id");
  if (!accountId) {
    throw Object.assign(new Error("identity unavailable"), { status: 502 });
  }
  const name = objectClaim(profile, "name");
  const email = stringClaim(profile, "email") || undefined;
  const displayName =
    firstNonEmpty(
      name?.display_name,
      name?.familiar_name,
      name?.abbreviated_name,
      email,
      accountId,
    ) || undefined;

  return {
    provider_user_id: accountId,
    provider_account_id: accountId,
    provider_account_name: email || displayName,
    email,
    display_name: displayName,
    metadata: profile,
  };
}

import {
  type CatalystExchangeResponse,
  disconnectGenesisOAuthConnection,
  genesisAuthUrl,
  genesisOAuthPost,
  listGenesisOAuthIntegrations,
} from "../lib/genesis-oauth";
import { type FileDriveRecord, replaceDropboxDriveMount } from "../storage/file-drive";
import { DROPBOX_OAUTH_SCOPES } from "./file-providers/dropbox";

export async function dropboxDriveOAuthConfigured(input: {
  orgId: string;
  userId: string;
}): Promise<boolean> {
  if (!genesisAuthUrl()) return false;
  try {
    const integrations = await listGenesisOAuthIntegrations(input.userId, {
      orgId: input.orgId,
      refresh: true,
    });
    return integrations.some(
      (integration) => integration.service === "dropbox" || integration.slug === "dropbox",
    );
  } catch {
    return false;
  }
}

export async function startDropboxDriveOAuthAuthorize(input: {
  orgId: string;
  userId: string;
  redirectUri: string;
  state: string;
}): Promise<string> {
  const data = await genesisOAuthPost<{ auth_url: string }>(
    "dropbox",
    "authorize",
    {
      redirect_uri: input.redirectUri,
      state: input.state,
      scopes: [...DROPBOX_OAUTH_SCOPES],
      genesis_user_id: input.userId,
    },
    { orgId: input.orgId },
  );
  if (!data.auth_url?.trim()) throw new Error("Dropbox authorize did not return an auth URL");
  return data.auth_url;
}

export async function completeDropboxDriveOAuth(input: {
  orgId: string;
  userId: string;
  code: string;
}): Promise<{ drive: FileDriveRecord }> {
  const exchange = await genesisOAuthPost<CatalystExchangeResponse>(
    "dropbox",
    "exchange",
    { code: input.code },
    { orgId: input.orgId },
  );
  if (exchange.genesis_user_id !== input.userId || exchange.org_id !== input.orgId) {
    throw new Error("Dropbox connect identity did not match the current user and organization");
  }
  const providerUserId = exchange.provider_user_id?.trim();
  if (!providerUserId) throw new Error("Dropbox connect did not return account identity");
  const accountLabel =
    exchange.email?.trim().toLowerCase() ||
    exchange.display_name?.trim() ||
    exchange.provider_account_name?.trim() ||
    providerUserId;

  const drive = await replaceDropboxDriveMount({
    orgId: input.orgId,
    userId: input.userId,
    providerUserId,
    displayName: `Dropbox · ${accountLabel}`,
  });
  return { drive };
}

export async function revokeDropboxDriveOAuth(input: {
  orgId: string;
  userId: string;
}): Promise<void> {
  await disconnectGenesisOAuthConnection({
    provider: "dropbox",
    genesisUserId: input.userId,
    orgId: input.orgId,
  });
}

import { isExpectedBrokerOAuthTokenError } from "../../lib/genesis-oauth";
import { markProviderDriveFileStatus } from "../../storage/drive-file";
import { updateFileDriveSyncState } from "../../storage/file-drive";
import { revokeDropboxDriveOAuth } from "../dropbox-drive-connection";
import { DropboxApiError, dropboxProvider } from "../file-providers/dropbox";
import type { MountedCloudDriveDriver } from "./types";

export const dropboxMountedCloudDriveDriver: MountedCloudDriveDriver = {
  id: "dropbox",
  driveKinds: ["dropbox"],
  provider: dropboxProvider,
  listingStrategy: "lazy",
  resolveAccessToken: async (input) => {
    if (
      input.drive.kind !== "dropbox" ||
      input.drive.ownerScopeType !== "user" ||
      input.drive.ownerScopeId !== input.userId ||
      input.drive.status === "disconnected"
    ) {
      return null;
    }
    try {
      const token = await dropboxProvider.getAccessToken(input.userId, { orgId: input.orgId });
      const tokenAccountId = await dropboxProvider.getAccountId?.(token);
      if (!tokenAccountId || tokenAccountId !== input.drive.providerAccountId) {
        await updateFileDriveSyncState({
          id: input.drive.id,
          status: "reauth_required",
          lastErrorCode: "dropbox_account_mismatch",
        });
        return null;
      }
      return token;
    } catch (error) {
      if (dropboxProvider.isAuthorizationError?.(error)) {
        await updateFileDriveSyncState({
          id: input.drive.id,
          status: "reauth_required",
          lastErrorCode: "dropbox_authorization_required",
        });
        return null;
      }
      if (isExpectedBrokerOAuthTokenError(error)) return null;
      throw error;
    }
  },
  disconnect: async (input) => {
    await revokeDropboxDriveOAuth({ orgId: input.orgId, userId: input.userId });
  },
  handleAccessLoss: async (input) => {
    if (dropboxProvider.isAuthorizationError?.(input.error)) {
      await updateFileDriveSyncState({
        id: input.drive.id,
        status: "reauth_required",
        lastErrorCode: "dropbox_authorization_required",
      });
      return false;
    }
    const itemAccessLost =
      dropboxProvider.isNotFoundError(input.error) ||
      (input.error instanceof DropboxApiError && input.error.status === 403);
    if (!itemAccessLost || !input.file.providerObjectId) return false;
    await markProviderDriveFileStatus({
      orgId: input.orgId,
      driveId: input.drive.id,
      scope: { type: "user", id: input.userId },
      providerObjectId: input.file.providerObjectId,
      status: "unavailable",
    });
    return true;
  },
};

{
  "id": "connection:dropbox",
  "name": "Dropbox",
  "description": "Dropbox files, search, sharing, file requests, and revisions through the Dropbox MCP server.",
  "connections": ["dropbox"],
  "runtime": {
    "delivery": {
      "dropbox": {
        "as": "mcp",
        "url": "https://mcp.dropbox.com/mcp",
        "transport": "http",
        "headers": { "Authorization": "Bearer {{token}}" }
      }
    }
  }
}

import { inferDriveFileUploadMimeType } from "../../domain/drive-file-content-policy";
import type { ProviderFileMetadata } from "../../domain/file";
import { getGenesisOAuthToken } from "../../lib/genesis-oauth";
import type { FileProviderAdapter } from "./types";

const DROPBOX_API_URL = "https://api.dropboxapi.com/2";
const DROPBOX_CONTENT_URL = "https://content.dropboxapi.com/2";
export const DROPBOX_FOLDER_MIME_TYPE = "application/vnd.dropbox.folder";
export const DROPBOX_ROOT_FOLDER_ID = "dropbox-root";
export const DROPBOX_OAUTH_SCOPES = [
  "account_info.read",
  "files.metadata.read",
  "files.content.read",
  "files.content.write",
  "sharing.read",
  "sharing.write",
  "file_requests.read",
  "file_requests.write",
] as const;

type DropboxMetadata = {
  ".tag"?: unknown;
  id?: unknown;
  name?: unknown;
  path_lower?: unknown;
  path_display?: unknown;
  client_modified?: unknown;
  server_modified?: unknown;
  rev?: unknown;
  size?: unknown;
  content_hash?: unknown;
};

type DropboxListFolderResult = {
  entries?: unknown;
  cursor?: unknown;
  has_more?: unknown;
};

type DropboxSearchResult = {
  matches?: unknown;
};

export class DropboxApiError extends Error {
  constructor(
    readonly status: number,
    readonly diagnosticDetail: string | null,
  ) {
    super("Dropbox API request failed");
    this.name = "DropboxApiError";
  }
}

function readString(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() ? value : undefined;
}

function isDropboxMetadata(value: unknown): value is DropboxMetadata {
  if (!value || typeof value !== "object" || !(".tag" in value)) return false;
  const tag = value[".tag"];
  return tag === "file" || tag === "folder";
}

function dropboxMimeType(metadata: DropboxMetadata): string {
  if (metadata[".tag"] === "folder") return DROPBOX_FOLDER_MIME_TYPE;
  return inferDriveFileUploadMimeType({ name: readString(metadata.name) ?? "file" });
}

export function dropboxMetadataToProviderMetadata(
  metadata: DropboxMetadata,
  parentId?: string,
): ProviderFileMetadata {
  const id = readString(metadata.id);
  const name = readString(metadata.name);
  const tag = readString(metadata[".tag"]);
  if (!id || !name || (tag !== "file" && tag !== "folder")) {
    throw new Error("Dropbox returned invalid file metadata");
  }
  const size =
    typeof metadata.size === "number" && Number.isSafeInteger(metadata.size) ? metadata.size : null;
  return {
    id,
    name,
    mimeType: dropboxMimeType(metadata),
    size: size == null ? null : String(size),
    createdTime: readString(metadata.client_modified) ?? null,
    modifiedTime: readString(metadata.server_modified) ?? null,
    md5Checksum: readString(metadata.content_hash) ?? null,
    version: readString(metadata.rev) ?? null,
    trashed: false,
    parents: parentId ? [parentId] : null,
  };
}

async function dropboxRequest(
  token: string,
  url: string,
  init?: RequestInit,
  timeoutMs: number | null = 30_000,
): Promise<Response> {
  const headers = new Headers(init?.headers);
  headers.set("Authorization", `Bearer ${token}`);
  const controller = !init?.signal && timeoutMs != null ? new AbortController() : null;
  const timeout = controller ? setTimeout(() => controller.abort(), timeoutMs ?? 0) : null;
  let response: Response;
  try {
    response = await fetch(url, {
      ...init,
      headers,
      signal: init?.signal ?? controller?.signal,
    });
  } finally {
    if (timeout) clearTimeout(timeout);
  }
  if (!response.ok) {
    const detail = (await response.text().catch(() => "")).slice(0, 4_000);
    throw new DropboxApiError(response.status, detail || null);
  }
  return response;
}

async function dropboxJson<T>(token: string, url: string, init: RequestInit): Promise<T> {
  const response = await dropboxRequest(token, url, init);
  // Dropbox is an untyped HTTP boundary; callers validate fields before use.
  return response.json() as Promise<T>;
}

async function dropboxRpc<T>(token: string, endpoint: string, body: object): Promise<T> {
  return dropboxJson<T>(token, `${DROPBOX_API_URL}/${endpoint}`, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
}

async function getDropboxMetadata(token: string, providerFileId: string): Promise<DropboxMetadata> {
  if (providerFileId === DROPBOX_ROOT_FOLDER_ID) {
    throw new Error("Dropbox root metadata is unavailable");
  }
  const metadata = await dropboxRpc<DropboxMetadata>(token, "files/get_metadata", {
    path: providerFileId,
    include_deleted: false,
  });
  if (!isDropboxMetadata(metadata)) throw new Error("Dropbox returned invalid file metadata");
  return metadata;
}

async function getDropboxPath(token: string, providerFileId: string): Promise<string> {
  if (providerFileId === DROPBOX_ROOT_FOLDER_ID) return "";
  const metadata = await getDropboxMetadata(token, providerFileId);
  const path = readString(metadata.path_display) ?? readString(metadata.path_lower);
  if (!path) throw new Error("Dropbox did not return a file path");
  return path;
}

function appendDropboxPath(parentPath: string, name: string): string {
  const cleanName = name.trim();
  if (!cleanName || cleanName.includes("/")) throw new Error("Invalid Dropbox file name");
  return `${parentPath}/${cleanName}`;
}

export async function getDropboxAccountId(token: string): Promise<string> {
  const account = await dropboxRpc<{ account_id?: unknown }>(
    token,
    "users/get_current_account",
    {},
  );
  const accountId = readString(account.account_id);
  if (!accountId) throw new Error("Dropbox did not return account identity");
  return `dropbox:${accountId}`;
}

async function getFileMetadata(
  token: string,
  providerFileId: string,
): Promise<ProviderFileMetadata> {
  return dropboxMetadataToProviderMetadata(await getDropboxMetadata(token, providerFileId));
}

async function createFolder(
  token: string,
  name: string,
  parentId = DROPBOX_ROOT_FOLDER_ID,
): Promise<string> {
  const parentPath = await getDropboxPath(token, parentId);
  const result = await dropboxRpc<{ metadata?: unknown }>(token, "files/create_folder_v2", {
    path: appendDropboxPath(parentPath, name),
    autorename: false,
  });
  if (!isDropboxMetadata(result.metadata)) {
    throw new Error("Dropbox did not return the new folder");
  }
  const id = readString(result.metadata.id);
  if (!id) throw new Error("Dropbox did not return the new folder id");
  return id;
}

async function uploadFile(
  token: string,
  folderId: string,
  name: string,
  content: Blob | string,
): Promise<ProviderFileMetadata> {
  const parentPath = await getDropboxPath(token, folderId);
  const response = await dropboxRequest(token, `${DROPBOX_CONTENT_URL}/files/upload`, {
    method: "POST",
    headers: {
      "Content-Type": "application/octet-stream",
      "Dropbox-API-Arg": JSON.stringify({
        path: appendDropboxPath(parentPath, name),
        mode: "add",
        autorename: false,
        mute: false,
      }),
    },
    body: content,
  });
  const metadata = (await response.json()) as unknown;
  if (!isDropboxMetadata(metadata)) throw new Error("Dropbox did not return the uploaded file");
  return dropboxMetadataToProviderMetadata(metadata, folderId);
}

async function updateFileContent(
  token: string,
  providerFileId: string,
  content: Blob | string,
): Promise<ProviderFileMetadata> {
  const response = await dropboxRequest(token, `${DROPBOX_CONTENT_URL}/files/upload`, {
    method: "POST",
    headers: {
      "Content-Type": "application/octet-stream",
      "Dropbox-API-Arg": JSON.stringify({
        path: providerFileId,
        mode: "overwrite",
        autorename: false,
        mute: false,
      }),
    },
    body: content,
  });
  const metadata = (await response.json()) as unknown;
  if (!isDropboxMetadata(metadata)) throw new Error("Dropbox did not return the updated file");
  return dropboxMetadataToProviderMetadata(metadata);
}

async function moveDropboxItem(
  token: string,
  providerFileId: string,
  targetPath: string,
): Promise<ProviderFileMetadata> {
  const result = await dropboxRpc<{ metadata?: unknown }>(token, "files/move_v2", {
    from_path: providerFileId,
    to_path: targetPath,
    autorename: false,
    allow_ownership_transfer: false,
  });
  if (!isDropboxMetadata(result.metadata)) throw new Error("Dropbox did not return the moved item");
  return dropboxMetadataToProviderMetadata(result.metadata);
}

async function updateFileMetadata(
  token: string,
  providerFileId: string,
  metadata: Partial<Pick<ProviderFileMetadata, "name" | "trashed">>,
): Promise<ProviderFileMetadata> {
  if (metadata.trashed !== undefined) throw new Error("Unsupported Dropbox trash operation");
  if (!metadata.name) return getFileMetadata(token, providerFileId);
  const current = await getDropboxMetadata(token, providerFileId);
  const currentPath = readString(current.path_display) ?? readString(current.path_lower);
  if (!currentPath) throw new Error("Dropbox did not return a file path");
  const slash = currentPath.lastIndexOf("/");
  const parentPath = slash <= 0 ? "" : currentPath.slice(0, slash);
  return moveDropboxItem(token, providerFileId, appendDropboxPath(parentPath, metadata.name));
}

async function moveFile(
  token: string,
  providerFileId: string,
  targetFolderId: string,
): Promise<ProviderFileMetadata> {
  const current = await getDropboxMetadata(token, providerFileId);
  const name = readString(current.name);
  if (!name) throw new Error("Dropbox did not return a file name");
  const targetPath = await getDropboxPath(token, targetFolderId);
  return moveDropboxItem(token, providerFileId, appendDropboxPath(targetPath, name));
}

async function deleteFile(token: string, providerFileId: string): Promise<void> {
  await dropboxRpc(token, "files/delete_v2", { path: providerFileId });
}

function listResultFiles(
  result: DropboxListFolderResult,
  parentId: string,
): ProviderFileMetadata[] {
  const entries = Array.isArray(result.entries) ? result.entries : [];
  return entries
    .filter(isDropboxMetadata)
    .map((metadata) => dropboxMetadataToProviderMetadata(metadata, parentId));
}

async function listFolderContentsPage(
  token: string,
  folderId: string,
  options?: { pageToken?: string; pageSize?: number },
): Promise<{ files: ProviderFileMetadata[]; nextPageToken?: string }> {
  const result = options?.pageToken
    ? await dropboxRpc<DropboxListFolderResult>(token, "files/list_folder/continue", {
        cursor: options.pageToken,
      })
    : await dropboxRpc<DropboxListFolderResult>(token, "files/list_folder", {
        path: folderId === DROPBOX_ROOT_FOLDER_ID ? "" : folderId,
        recursive: false,
        include_deleted: false,
        include_mounted_folders: true,
        include_non_downloadable_files: true,
        limit: Math.min(2_000, Math.max(1, options?.pageSize ?? 1_000)),
      });
  const cursor = readString(result.cursor);
  const nextPageToken = result.has_more === true ? cursor : undefined;
  return {
    files: listResultFiles(result, folderId),
    ...(nextPageToken ? { nextPageToken } : {}),
  };
}

async function listFolderContents(
  token: string,
  folderId: string,
): Promise<ProviderFileMetadata[]> {
  const files: ProviderFileMetadata[] = [];
  let pageToken: string | undefined;
  do {
    const page = await listFolderContentsPage(token, folderId, { pageToken });
    files.push(...page.files);
    pageToken = page.nextPageToken;
  } while (pageToken);
  return files;
}

async function searchFiles(
  token: string,
  query: string,
  options?: { limit?: number },
): Promise<ProviderFileMetadata[]> {
  const result = await dropboxRpc<DropboxSearchResult>(token, "files/search_v2", {
    query,
    options: {
      max_results: Math.min(1_000, Math.max(1, options?.limit ?? 20)),
      file_status: "active",
    },
  });
  const matches = Array.isArray(result.matches) ? result.matches : [];
  return matches.flatMap((match) => {
    if (!match || typeof match !== "object" || !("metadata" in match)) return [];
    const wrapper = match.metadata;
    if (!wrapper || typeof wrapper !== "object" || !("metadata" in wrapper)) return [];
    const metadata = wrapper.metadata;
    return isDropboxMetadata(metadata) ? [dropboxMetadataToProviderMetadata(metadata)] : [];
  });
}

async function getFileContent(
  token: string,
  providerFileId: string,
  headers?: Record<string, string>,
): Promise<Response> {
  return dropboxRequest(token, `${DROPBOX_CONTENT_URL}/files/download`, {
    method: "POST",
    headers: {
      ...headers,
      "Dropbox-API-Arg": JSON.stringify({ path: providerFileId }),
    },
  });
}

export const dropboxProvider = {
  id: "dropbox",
  displayName: "Dropbox",
