  createFolder,
  createFile: async (token, name, _mimeType, parentId = DROPBOX_ROOT_FOLDER_ID) =>
    uploadFile(token, parentId, name, ""),
  uploadFile,
  getFileMetadata,
  updateFileMetadata,
  updateFileContent,
  moveFile,
  deleteFile,
