function secureContentHeaders(name: string, mimeType: string): Headers {
  return new Headers({
    "Content-Type": mimeType,
    "Content-Disposition": driveFileContentDisposition(name, mimeType),
    "Content-Security-Policy": DRIVE_FILE_CONTENT_SECURITY_POLICY,
