export type FileDriveKind =
  | "genesis_s3"
  /**
   * @deprecated GFD-401 — legacy identity mount. Product retires these to
   * `disconnected` on Files open. Prefer `google_my_drive` / `google_workspace_drive`.
   */
  | "google_drive"
  | "google_my_drive"
  | "google_workspace_drive"
  | "box"
  | "dropbox";
export type FileDriveOwnerScope = "user" | "org";
export type FileScope = "user" | "team" | "org";
export type FileLocatorKind = "s3_object" | "provider_object" | "native_object";

export type FileDriveCapability =
  | "enumerate"
  | "read"
  | "range_read"
  | "create_file"
  | "create_folder"
  | "upload"
  | "rename"
  | "move"
  | "trash"
  | "delete"
  | "preview"
  | "export"
  | "incremental_sync"
  | "change_notifications"
  | "search"
  /** Google My Drive: open native Google File Picker to grant file/folder access. */
  | "picker_add";

/** True for any Google-backed mount kind (legacy or dual-drive model). */
export function isGoogleFileDriveKind(kind: string): boolean {
  return kind === "google_drive" || kind === "google_my_drive" || kind === "google_workspace_drive";
}

/** True for any external provider mounted through a cloud-drive driver. */
export function isMountedCloudFileDriveKind(kind: string): boolean {
  return isGoogleFileDriveKind(kind) || kind === "box" || kind === "dropbox";
}

export function isBoxFileDriveKind(kind: string): boolean {
  return kind === "box";
}

export function isDropboxFileDriveKind(kind: string): boolean {
  return kind === "dropbox";
}

export function isGoogleMyDriveKind(kind: string): boolean {
  return kind === "google_my_drive";
}

export function isGoogleWorkspaceDriveKind(kind: string): boolean {
  return kind === "google_workspace_drive";
}

export interface DriveObjectFingerprint {
  providerVersion?: string;
  etag?: string;
  contentHash?: string;
  modifiedAt?: string;
  sizeBytes?: number;
  metadataHash: string;
}

export type GenesisDriveScope =
  | { type: "user"; userId: string }
  | { type: "team"; teamId: string }
  | { type: "org"; orgId: string };

export interface FileDriveScopeRecord {
  kind: string;
  ownerScopeType: string;
  ownerScopeId: string;
}

export type ViewerFileScope = { type: FileScope; id: string };

export function canReadDriveFileContent(status: string): boolean {
  return status === "active" || status === "trashed";
}

export function fileDriveScopeForViewer(
  drive: FileDriveScopeRecord,
  viewer: { orgId: string; userId: string },
): ViewerFileScope | null {
  if (drive.kind === "genesis_s3") {
    if (drive.ownerScopeType === "user" && drive.ownerScopeId === viewer.userId) {
      return { type: "user", id: viewer.userId };
    }
    if (drive.ownerScopeType === "org" && drive.ownerScopeId === viewer.orgId) {
      return { type: "org", id: viewer.orgId };
    }
    return null;
  }

  if (
    isMountedCloudFileDriveKind(drive.kind) &&
    drive.ownerScopeType === "user" &&
    drive.ownerScopeId === viewer.userId
  ) {
    return { type: "user", id: viewer.userId };
  }
  return null;
}


