import { providerMcpConfig, registryProviderLogo } from "./oauth-provider-registry";

describe("oauth-provider-registry", () => {
  test("accepts only data-uri logos from Ion", () => {
    expect(registryProviderLogo("data:image/svg+xml;base64,abc")).toBe(
      "data:image/svg+xml;base64,abc",
    );
    expect(registryProviderLogo("https://example.com/logo.svg")).toBeNull();
    expect(registryProviderLogo(null)).toBeNull();
  });

  test("parses runtime_config mcp_config", () => {
    const config = providerMcpConfig({
      runtime_config: {
        mcp_config: {
          type: "remote",
          url: "https://ai.todoist.net/mcp",
          transport: "http",
          headerMapping: { Authorization: "Bearer {{accessToken}}" },
        },
      },
    });

    expect(config?.type).toBe("remote");
  });
});

