const originalFetch = globalThis.fetch;
const originalAdminSecret = process.env.AUTH_ADMIN_SECRET;
const originalAuthUrl = process.env.GENESIS_OAUTH_AUTH_URL;

afterEach(() => {
  globalThis.fetch = originalFetch;
  if (originalAdminSecret === undefined) delete process.env.AUTH_ADMIN_SECRET;
  else process.env.AUTH_ADMIN_SECRET = originalAdminSecret;
  if (originalAuthUrl === undefined) delete process.env.GENESIS_OAUTH_AUTH_URL;
  else process.env.GENESIS_OAUTH_AUTH_URL = originalAuthUrl;
});

describe("redactOpsOAuthConnection", () => {
  test("never exposes client_secret and reports configuration", () => {
    const view = redactOpsOAuthConnection({
      service: "xero",
      credential_strategy: "static",
      lifecycle_status: "experimental",
      handler_kind: "xero",
      client_id: "client",
      client_secret: "super-secret-value",
      auth_url: "https://example.com/auth",
      token_url: "https://example.com/token",
      default_scopes: ["openid"],
      experimental_org_ids: ["org_1"],
      pkce: false,
      public_client: false,
    });
    expect(view.clientSecretConfigured).toBe(true);
