  test("registers all Catalyst handler kinds", () => {
    expect(HANDLER_KINDS.sort()).toEqual(
      [
        "attio",
        "calcom",
        "dropbox",
        "generic",
        "github",
        "gusto",
        "housecallpro",
        "hubspot",
        "jobber",
        "linear",
        "mercury",
        "notion",
        "quickbooks",
        "sage",
        "slack",
        "todoist",
        "wave",
        "xero",
      ].sort(),
    );
  });

  test("generic slug fallback routes to named handler", () => {
    const handler = resolveHandler("generic", "github");
    expect(handler.identity.name || "ok").toBeTruthy();
    // Distinct from pure generic: github identity does not require user_info_url.
    expect(handler).not.toBe(resolveHandler("generic"));
  });
});

