describe("Dropbox drive broker connection", () => {
  it("reports Dropbox availability from the tenant-visible broker registry", async () => {
    const { dropboxDriveOAuthConfigured } = await import("./dropbox-drive-connection");

    await expect(dropboxDriveOAuthConfigured({ orgId: "org-1", userId: "user-1" })).resolves.toBe(
      true,
    );
    listGenesisOAuthIntegrationsMock.mockResolvedValue([]);
    await expect(dropboxDriveOAuthConfigured({ orgId: "org-1", userId: "user-1" })).resolves.toBe(
      false,
    );
  });

  it("starts broker OAuth with the Dropbox REST and MCP scopes", async () => {
    genesisOAuthPostMock.mockResolvedValue({
      auth_url: "https://www.dropbox.com/oauth2/authorize",
    });
    const { startDropboxDriveOAuthAuthorize } = await import("./dropbox-drive-connection");

    await expect(
      startDropboxDriveOAuthAuthorize({
        orgId: "org-1",
        userId: "user-1",
        redirectUri: "https://app.example/api/drive-files/dropbox/callback",
        state: "state-1",
      }),
    ).resolves.toBe("https://www.dropbox.com/oauth2/authorize");
    expect(genesisOAuthPostMock).toHaveBeenCalledWith(
      "dropbox",
      "authorize",
      expect.objectContaining({
        redirect_uri: "https://app.example/api/drive-files/dropbox/callback",
        state: "state-1",
        scopes: expect.arrayContaining([
          "account_info.read",
          "files.metadata.read",
          "files.content.read",
          "files.content.write",
          "sharing.write",
        ]),
        genesis_user_id: "user-1",
      }),
      { orgId: "org-1" },
    );
  });

  it("mounts the exchanged Dropbox account without storing tokens locally", async () => {
    genesisOAuthPostMock.mockResolvedValue({
      org_id: "org-1",
      genesis_user_id: "user-1",
      user_id: "user-1",
      provider: "dropbox",
      provider_user_id: "dbid:THISISAVERYLONGANDVERYOBVIOUSTESTACCOUNT",
      provider_account_name: "ada@example.com",
      scopes: ["files.metadata.read"],
    });
    const { completeDropboxDriveOAuth } = await import("./dropbox-drive-connection");

    await expect(
      completeDropboxDriveOAuth({ orgId: "org-1", userId: "user-1", code: "exchange-code" }),
