    expect(replaceDropboxDriveMountMock).toHaveBeenCalledWith({
      orgId: "org-1",
      userId: "user-1",
      providerUserId: "dbid:THISISAVERYLONGANDVERYOBVIOUSTESTACCOUNT",
      displayName: "Dropbox · ada@example.com",
    });
