import { useSession } from "@web/lib/auth";
import { cn } from "@web/lib/utils";
import {
  Check,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  Copy,
  ExternalLink,
  FileJson,
  Loader2,
  Plus,
  ShieldCheck,
  Upload,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { GoogleMyDriveConnectOverview } from "./google-my-drive-connect-overview";

const GOOGLE_CLOUD_CONSOLE_URL = "https://console.cloud.google.com/";
const GOOGLE_DRIVE_API_URL = "https://console.cloud.google.com/apis/library/drive.googleapis.com";
const GOOGLE_SERVICE_ACCOUNT_URL =
  "https://console.cloud.google.com/iam-admin/serviceaccounts/create";
const GOOGLE_SERVICE_ACCOUNT_KEY_HELP_URL =
  "https://cloud.google.com/iam/docs/keys-create-delete#creating";
const GOOGLE_DOMAIN_WIDE_DELEGATION_URL = "https://admin.google.com/ac/owl/domainwidedelegation";
const GOOGLE_DOMAIN_WIDE_DELEGATION_HELP_URL =
  "https://developers.google.com/identity/protocols/oauth2/service-account#delegatingauthority";

const GOOGLE_SETUP_STEPS = [
  {
    title: "Before you begin",
    description: "Confirm that you have the access needed to set up Google Workspace Drive.",
  },
  {
    title: "Create a service account",
    description: "Prepare a customer-owned Google Cloud service account for Genesis.",
  },
  {
    title: "Authorize Workspace access",
    description: "Allow the service account to access Drive on behalf of your organization.",
  },
  {
    title: "Verify and connect",
    description: "Review the service account and test the connection before finishing.",
  },
] as const;

type ProviderId = "google_my_drive" | "google_workspace" | "sharepoint" | "box" | "dropbox";

type ServiceAccountCredential = {
  clientId: string;
  clientEmail: string;
  projectId: string;
};

function parseServiceAccountCredential(value: unknown): ServiceAccountCredential | null {
  if (!value || typeof value !== "object") {
    return null;
  }

  const credential = value as Record<string, unknown>;
  if (
    credential.type !== "service_account" ||
    typeof credential.client_id !== "string" ||
    !/^\d+$/.test(credential.client_id) ||
    typeof credential.client_email !== "string" ||
    credential.client_email.length === 0 ||
    typeof credential.project_id !== "string" ||
    credential.project_id.length === 0 ||
    typeof credential.private_key_id !== "string" ||
    credential.private_key_id.length === 0 ||
    typeof credential.private_key !== "string" ||
    !credential.private_key.includes("BEGIN PRIVATE KEY")
  ) {
    return null;
  }

  return {
    clientId: credential.client_id,
    clientEmail: credential.client_email,
    projectId: credential.project_id,
  };
}

type ProviderOption = {
  id: ProviderId;
  name: string;
  description: string;
  available: boolean;
  icon: React.ReactNode;
};

const PROVIDERS: ProviderOption[] = [
  {
    id: "google_my_drive",
    name: "Google My Drive",
    description: "Connect a personal or work Google account.",
    available: true,
    icon: <img src="/google-drive.svg" alt="" className="size-5" />,
  },
  {
    id: "google_workspace",
    name: "Google Workspace Drive",
    description:
      "Connect a Workspace domain with a service account. You can add more than one domain.",
    available: true,
    icon: (
      <img
        src="/google-drive.svg"
        alt=""
        className="size-5"
        style={{ filter: "hue-rotate(200deg) saturate(0.85)" }}
      />
    ),
  },
  {
    id: "sharepoint",
    name: "Microsoft SharePoint",
    description: "Connect SharePoint sites and document libraries.",
    available: false,
    icon: <img src="/sharepoint.svg" alt="" className="size-5 object-contain" />,
  },
  {
    id: "box",
    name: "Box",
