/**
 * User-facing disconnect for cloud file mounts (not Genesis S3).
 * Marks the mount disconnected, drops credentials when applicable, and purges
 * indexed drive_file rows in the background.
 */

import { eq } from "drizzle-orm";
import { db } from "../lib/db";
import { fileDrive } from "../lib/schema";
import { deleteDriveFiles, listDriveFiles } from "../storage/drive-file";
import { getFileDrive, listFileDrives } from "../storage/file-drive";
import { notifyDriveFilesChanged } from "./drive-files-realtime";
import { disconnectGoogleMyDriveAccount } from "./google-my-drive-accounts";
import { getMountedCloudDriveDriver } from "./mounted-cloud-drive-drivers";

async function purgeDriveIndex(input: {
  orgId: string;
  userId: string;
  driveId: string;
}): Promise<number> {
  const scope = { type: "user" as const, id: input.userId };
  const active = await listDriveFiles({
    orgId: input.orgId,
    driveId: input.driveId,
    scope,
    status: "active",
  });
  const trashed = await listDriveFiles({
    orgId: input.orgId,
    driveId: input.driveId,
    scope,
    status: "trashed",
  });
  const ids = [...active, ...trashed].map((file) => file.id);
  if (ids.length === 0) return 0;
  await deleteDriveFiles({ ids, orgId: input.orgId, scope });
  return ids.length;
}

function scheduleIndexPurge(input: {
  orgId: string;
  userId: string;
  driveId: string;
  label: string;
}): void {
  void purgeDriveIndex(input)
    .then((count) => {
      if (count > 0) {
        console.info(`[${input.label}] purged index after disconnect`, {
          driveId: input.driveId,
          files: count,
        });
      }
    })
    .catch((error) => {
      console.warn(`[${input.label}] background index purge failed`, {
        driveId: input.driveId,
        message: error instanceof Error ? error.message : String(error),
      });
    });
}

async function markDriveDisconnected(driveId: string, lastErrorCode: string | null): Promise<void> {
  await db
    .update(fileDrive)
    .set({
      status: "disconnected",
      lastErrorCode,
      updatedAt: new Date(),
    })
    .where(eq(fileDrive.id, driveId));
}

/**
 * Disconnect one cloud mount for the current user.
 * Genesis drives are rejected — use product APIs that own those corpora.
 */
export async function disconnectCloudFileDrive(input: {
  orgId: string;
  userId: string;
  driveId: string;
}): Promise<{ driveId: string; kind: string }> {
  const drive = await getFileDrive({ id: input.driveId, orgId: input.orgId });
  if (!drive || drive.status === "disconnected") {
    throw Object.assign(new Error("Drive not found"), { status: 404 });
  }
  if (drive.ownerScopeType === "user" && drive.ownerScopeId !== input.userId) {
    throw Object.assign(new Error("Drive not found"), { status: 404 });
  }

  if (drive.kind === "google_my_drive") {
    const accountId = drive.connectionId?.trim();
    if (!accountId) {
      throw Object.assign(new Error("Google My Drive connection is missing"), { status: 400 });
    }
    await disconnectGoogleMyDriveAccount({
      orgId: input.orgId,
      userId: input.userId,
      accountId,
    });
    notifyDriveFilesChanged({
      orgId: input.orgId,
      ownerUserId: input.userId,
      driveId: drive.id,
    });
    return { driveId: drive.id, kind: drive.kind };
  }

  if (drive.kind === "google_workspace_drive" || drive.kind === "google_drive") {
    // User-level mount teardown only — org Workspace SA credentials stay for admins.
    await markDriveDisconnected(
      drive.id,
      drive.kind === "google_workspace_drive" ? "workspace_drive_user_disconnected" : null,
    );
    scheduleIndexPurge({
      orgId: input.orgId,
      userId: input.userId,
      driveId: drive.id,
      label:
        drive.kind === "google_workspace_drive" ? "google-workspace-drive" : "google-drive-legacy",
    });
    notifyDriveFilesChanged({
      orgId: input.orgId,
      ownerUserId: input.userId,
      driveId: drive.id,
    });
    return { driveId: drive.id, kind: drive.kind };
  }

  const driver = getMountedCloudDriveDriver(drive.kind);
  if (driver) {
    await driver.disconnect?.({
      orgId: input.orgId,
      userId: input.userId,
      drive,
    });
    await markDriveDisconnected(drive.id, null);
    scheduleIndexPurge({
      orgId: input.orgId,
      userId: input.userId,
      driveId: drive.id,
      label: driver.id,
    });
    notifyDriveFilesChanged({
      orgId: input.orgId,
      ownerUserId: input.userId,
      driveId: drive.id,
    });
    return { driveId: drive.id, kind: drive.kind };
  }

  throw Object.assign(new Error("Only cloud drives can be disconnected here"), {
    status: 400,
  });
}

/** For Workspace group header: disconnect every active mount for this connection + user. */
export async function disconnectWorkspaceConnectionForUser(input: {
  orgId: string;
  userId: string;
  connectionId: string;
}): Promise<{ driveIds: string[] }> {
  const connectionId = input.connectionId.trim();
  if (!connectionId) {
    throw Object.assign(new Error("Connection id is required"), { status: 400 });
  }
  const mounts = (await listFileDrives(input.orgId)).filter(
    (drive) =>
      drive.kind === "google_workspace_drive" &&
      drive.connectionId === connectionId &&
      drive.ownerScopeType === "user" &&
      drive.ownerScopeId === input.userId &&
      drive.status !== "disconnected",
  );

  const driveIds: string[] = [];
  for (const mount of mounts) {
    await markDriveDisconnected(mount.id, "workspace_drive_user_disconnected");
    scheduleIndexPurge({
      orgId: input.orgId,
      userId: input.userId,
      driveId: mount.id,
      label: "google-workspace-drive",
    });
    driveIds.push(mount.id);
    notifyDriveFilesChanged({
      orgId: input.orgId,
      ownerUserId: input.userId,
      driveId: mount.id,
    });
  }
  return { driveIds };
}

