/**
 * Manifest lives inside the implementation package metadata on synced
 * templates; some fixtures also mirror it at the record metadata top level.
 */
export function readConnectionTemplateManifest(
  record: CapabilityRecord | undefined,
): ConnectionTemplateManifest | undefined {
  const topLevel = record?.metadata?.connectionTemplateManifest;
  if (topLevel && typeof topLevel === "object") {
    return topLevel as ConnectionTemplateManifest;
  }
  const pkg = record?.metadata?.[CAPABILITY_PACKAGE_METADATA_KEY] as
    | CapabilityImplementationPackage
    | undefined;
  const packaged = pkg?.metadata?.connectionTemplateManifest;
  return packaged && typeof packaged === "object"
    ? (packaged as ConnectionTemplateManifest)
    : undefined;
}

export function readConnectionTemplateMetadata(
  record: CapabilityRecord | undefined,
): ConnectionTemplateMetadata | undefined {
  const value = record?.metadata?.[CONNECTION_TEMPLATE_METADATA_KEY];
  if (!value || typeof value !== "object") return undefined;
  const metadata = value as Partial<ConnectionTemplateMetadata>;
  if (
    typeof metadata.slug !== "string" ||
    typeof metadata.contentHash !== "string" ||
    metadata.scope !== "system"
  ) {
    return undefined;
  }
  return metadata as ConnectionTemplateMetadata;
}

