import type { OAuthConnection, ProviderIdentity, TokenBundle } from "../types";
import {
  asString,
  fetchWithTimeout,
  firstNonEmpty,
  type JsonObject,
  readJson,
  tokenBundleFromOAuthJson,
} from "./util";

export type TokenExchangeInput = {
  connection: OAuthConnection;
  code: string;
  redirectUri: string;
  codeVerifier?: string;
};

export async function exchangeAuthorizationCode(input: TokenExchangeInput): Promise<TokenBundle> {
  const body = new URLSearchParams({
    grant_type: "authorization_code",
    code: input.code,
    redirect_uri: input.redirectUri,
    client_id: input.connection.client_id,
  });
  if (!input.connection.public_client) {
    body.set("client_secret", input.connection.client_secret);
  }
  if (input.codeVerifier) body.set("code_verifier", input.codeVerifier);

  const res = await fetchWithTimeout(input.connection.token_url, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });
  const raw = await readJson(res);
  if (!res.ok) {
    throw Object.assign(new Error(`token exchange failed: ${res.status}`), {
      status: 502,
      details: raw,
      upstream_status: res.status,
    });
  }
  return tokenBundleFromOAuthJson(raw);
}

export async function refreshAccessToken(
  connection: OAuthConnection,
  refreshToken: string,
): Promise<TokenBundle> {
  const body = new URLSearchParams({
    grant_type: "refresh_token",
    refresh_token: refreshToken,
    client_id: connection.client_id,
  });
  if (!connection.public_client) body.set("client_secret", connection.client_secret);

  const res = await fetchWithTimeout(connection.token_url, {
    method: "POST",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });
  const raw = await readJson(res);
  if (!res.ok) {
    // A provider rejecting the grant (expired/revoked/already-rotated refresh
    // token) needs a reconnect, not a gateway retry. Callers treat 401 as an
    // expected "not connected" signal, while 502 reads as a broker outage.
    const grantRejected = res.status === 400 || res.status === 401;
    throw Object.assign(new Error(`refresh failed: ${res.status}`), {
      status: grantRejected ? 401 : 502,
      details: raw,
      upstream_status: res.status,
    });
  }
  const bundle = tokenBundleFromOAuthJson(raw);
  return {
    ...bundle,
    refresh_token: bundle.refresh_token ?? refreshToken,
  };
}

export async function fetchGenericIdentity(
  connection: OAuthConnection,
  accessToken: string,
): Promise<ProviderIdentity> {
  if (!connection.user_info_url) {
    throw Object.assign(new Error("generic oauth handler requires user_info_url"), { status: 500 });
  }
  const res = await fetchWithTimeout(connection.user_info_url, {
    headers: {
      Accept: "application/json",
      Authorization: `Bearer ${accessToken}`,
    },
  });
  const raw = await readJson(res);
  if (!res.ok) {
    throw Object.assign(new Error(`identity fetch failed: ${res.status}`), {
      status: 502,
      details: raw,
      upstream_status: res.status,
    });
  }
  return identityFromUserInfo(raw);
}

export function identityFromUserInfo(profile: JsonObject): ProviderIdentity {
  const providerUserId = firstNonEmpty(profile.sub, profile.id, profile.user_id, profile.userId);
  if (!providerUserId) {
    throw Object.assign(new Error("identity unavailable"), { status: 502 });
  }
  const accountName = firstNonEmpty(
    profile.login,
    profile.username,
    profile.preferred_username,
    providerUserId,
  );
  const displayName = firstNonEmpty(
    profile.display_name,
    profile.full_name,
    profile.name,
    profile.username,
    profile.login,
  );
  return {
    provider_user_id: providerUserId,
    provider_account_id: accountName,
    provider_account_name: accountName,
    email: asString(profile.email),
    display_name: displayName || undefined,
    metadata: profile,
  };
}

import { fetchWithTimeout, firstNonEmpty, readJson } from "../handlers/util";
import type { BrokerStore } from "../store/types";
import type { CredentialStrategy, OAuthConnection } from "../types";

const dcrLocks = new Map<string, Promise<OAuthConnection>>();
const DEFAULT_DCR_LOGO = "https://agentcompany.com/genesis/Icon.svg";

function needsDcr(connection: OAuthConnection): boolean {
  if (connection.credential_strategy !== "dcr") return false;
  const clientId = connection.client_id.trim();
  if (!clientId || clientId === "pending-dcr") return true;
  if (!connection.public_client && !connection.client_secret.trim()) return true;
  return false;
}

export async function ensureDcrCredentials(input: {
  store: BrokerStore;
  service: string;
  strategy: CredentialStrategy;
  connection: OAuthConnection;
  authBaseUrl: string;
  scopes: string[];
}): Promise<OAuthConnection> {
  if (!needsDcr(input.connection)) return input.connection;

  const lockKey = `${input.service}/${input.strategy}`;
  const inflight = dcrLocks.get(lockKey);
  if (inflight) return inflight;

  const run = (async () => {
    const latest = await input.store.getConnection(input.service, input.strategy);
    if (!latest) throw Object.assign(new Error("OAuth connection not found"), { status: 404 });
    if (!needsDcr(latest)) return latest;

    if (!latest.dcr_registration_url?.trim() || !latest.dcr_client_name?.trim()) {
      throw Object.assign(new Error("dcr registration config incomplete"), { status: 500 });
    }

    const redirectUri = `${input.authBaseUrl.replace(/\/$/, "")}/genesis/oauth/${input.service}/${input.strategy}/callback`;
    const scope = [...new Set(input.scopes.map((s) => s.trim()).filter(Boolean))].sort().join(" ");
    const body: Record<string, unknown> = {
      ...(latest.dcr_extra_registration_params ?? {}),
      redirect_uris: [redirectUri],
      client_name: latest.dcr_client_name.trim(),
      logo_uri: latest.dcr_logo_uri?.trim() || DEFAULT_DCR_LOGO,
      scope,
    };

    const res = await fetchWithTimeout(latest.dcr_registration_url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify(body),
    });
    const raw = await readJson(res);
    if (res.status < 200 || res.status >= 300) {
      throw Object.assign(new Error(`dcr registration failed: ${res.status}`), {
        status: 502,
        details: raw,
      });
    }

    const clientId = firstNonEmpty(raw.client_id);
    const clientSecret = firstNonEmpty(raw.client_secret);
    if (!clientId) {
      throw Object.assign(new Error("dcr registration response missing client_id"), {
        status: 502,
      });
    }
    if (!latest.public_client && !clientSecret) {
      throw Object.assign(new Error("dcr registration response missing client_secret"), {
        status: 502,
      });
    }

    return input.store.upsertConnection({
      ...latest,
      client_id: clientId,
      client_secret: clientSecret || latest.client_secret,
      dcr_registered_at: new Date(),
    });
  })();

  dcrLocks.set(lockKey, run);
  try {
    return await run;
  } finally {
    dcrLocks.delete(lockKey);
  }
}

