export function isRegistryOAuthProvider(
  provider: string,
  integrations?: readonly GenesisOAuthIntegration[],
): boolean {
  const normalized = provider.trim().toLowerCase();
  const list = integrations ?? [];
  return list.some((item) => item.slug === normalized);
}

export async function findRegistryOAuthIntegration(
  genesisUserId: string,
  slug: string,
  options?: { refresh?: boolean; orgId?: string | null },
): Promise<GenesisOAuthIntegration | null> {
  const integrations = await listGenesisOAuthIntegrations(genesisUserId, options);
  return integrations.find((item) => item.slug === slug) ?? null;

